// PDF viewer: the PDF files on the frame's card, read on the frame. The
// library lists every .pdf below the scene's folder (the whole card by
// default), the one read last first; a document opens where you left it.
//
// pdf.js reads the file a piece at a time and turns a page into what to draw
// in the screen's pixels: paths, words and pictures. They are drawn here as
// one SVG, the words in the frame's face stretched to the widths the PDF
// gives them (bold drawn with a thin outline, italic slanted: the frame has
// one face), the pictures decoded by the frame straight from the file at the
// size they are drawn. A page that is taller than the screen is wide is read
// at the screen's width a part at a time ("Fit width"); "Whole page" fits it
// all. The PDF's bookmarks are its contents, and a page can be gone to by its
// number.
//
// Where you are is the private `spot` field, kept on disk: the document, its
// page and part, and where every document read lately was left. A document
// handed over by another scene (the Files app, through `settings.opens`)
// comes in the public field `file`, "<storage>:<path>", and opens where it was
// left.
//
// Taps: the left third goes back, the rest forward; swipes and the keys turn
// pages too (UP / LEFT back, DOWN / RIGHT forward, any other key back to the
// library; held keys stay the frame's).

import { PdfDocument, renderPage, pageSize } from './pdf'

const DOCS_KEPT = 40
const LIST_MS = 5 * 60 * 1000
const OVERLAP = 0.06 // of a part's height, seen again on the next part

let zoom = 1
const px = (n) => `${Math.round(n * zoom)}px`
const raw = (n) => `${Math.round(n)}px`

// What lives only as long as the interpreter: the document open, the page
// drawn, the library listed.
let opened = null // { key, doc, title, outline }
let drawn = { key: '', ops: [], problems: [], size: null }
let listed = { folder: null, at: 0, docs: [] }

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const saveSpot = (spot) => frameos.setState('spot', spot)
const baseName = (path) => path.split('/').pop()

// A document is "<storage>:<path>": which of app.frame.storages it is in
// (the TF card's "assets", "internal") and its path there.
const STORAGE_IDS = ['assets', 'internal']
function placeOf(key) {
  const at = key.indexOf(':')
  const storage = at > 0 ? key.slice(0, at) : ''
  return STORAGE_IDS.includes(storage) ? { storage, path: key.slice(at + 1) } : { storage: 'assets', path: key }
}
const keyOf = (storage, path) => `${storage}:${path}`
const docName = (key) => baseName(placeOf(key).path).replace(/\.pdf$/i, '').replace(/[_]+/g, ' ')

function storagesOf(app) {
  const storages = Array.isArray(app.frame.storages) ? app.frame.storages.filter((s) => s && STORAGE_IDS.includes(s.id)) : []
  return storages.length > 0 ? storages : [{ id: 'assets', name: 'Internal storage' }]
}

// ---- Reading the file ----------------------------------------------------------

function ioFor(key) {
  const at = placeOf(key)
  const size = frameos.assetSize(at.path, { storage: at.storage })
  return {
    size,
    read: (offset, length) => frameos.readAsset(at.path, { offset, length, bytes: true, storage: at.storage }),
    inflate: (offset, length) => frameos.readAsset(at.path, { offset, length, inflate: true, bytes: true, storage: at.storage }),
  }
}

// The document, opened once while the interpreter lives.
function openDoc(key) {
  if (opened && opened.key === key) return opened
  opened = null
  drawn = { key: '', ops: [], problems: [], size: null }
  try {
    const io = ioFor(key)
    if (!(io.size > 0)) return { key, error: 'The file is not there' }
    const doc = new PdfDocument(io)
    const info = doc.info()
    opened = { key, doc, title: info.title || docName(key), author: info.author, pages: doc.pageCount, outline: null }
    return opened
  } catch (e) {
    const why = e && e.message ? e.message : String(e)
    return { key, error: why ? why[0].toUpperCase() + why.slice(1) : 'Not a PDF' }
  }
}

function outlineOf(opened) {
  if (opened.outline === null) {
    try {
      opened.outline = opened.doc.outline().filter((item) => item.page >= 0)
    } catch (e) {
      opened.outline = []
    }
  }
  return opened.outline
}

// ---- Where the page goes ------------------------------------------------------------

// The room for the page, between the bars.
function viewOf(ui) {
  const bar = Math.round(40 * zoom)
  const foot = Math.round(26 * zoom)
  return { top: bar, width: ui.width, height: Math.max(40, ui.height - bar - foot), bar, foot }
}

// How a page sits in the view: its scale, where its corner is, and how many
// parts it is read in.
function placement(size, view, fit) {
  const margin = Math.round(6 * zoom)
  const roomW = view.width - margin * 2
  const roomH = view.height - margin * 2
  const whole = Math.min(roomW / size.width, roomH / size.height)
  const wide = roomW / size.width
  // Fit width only when it makes the page half as big again: a landscape
  // page on a landscape screen is read whole.
  const byWidth = fit === 'width' || (fit !== 'page' && wide > whole * 1.5)
  if (!byWidth) {
    const w = size.width * whole
    const h = size.height * whole
    return { scale: whole, x: (view.width - w) / 2, y: (view.height - h) / 2, parts: 1, byWidth, step: 0 }
  }
  const h = size.height * wide
  const step = view.height * (1 - OVERLAP)
  const parts = h <= view.height ? 1 : 1 + Math.ceil((h - view.height) / step)
  return { scale: wide, x: margin, y: h <= view.height ? (view.height - h) / 2 : 0, parts, byWidth, step, h }
}

function partY(place, view, part) {
  if (place.parts <= 1) return place.y
  // The last part ends at the page's bottom.
  return -Math.min(part * place.step, place.h - view.height)
}

// ---- Looks ---------------------------------------------------------------------------

function uiOf(app, context) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const fast = app.frame.fast ?? !paper
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // Sized for 480 px of the room's shorter side, smaller under it; a bigger
  // screen is made larger by the frame's render scale, not here.
  const shortSide = Math.min(width, height)
  zoom = Math.max(0.75, Math.min(1, Math.round((shortSide / 480) * 4) / 4))
  // A round panel: the library and the pages in the square inside the
  // circle, the type as big as the whole panel would have it.
  const side = context && context.round === true ? Math.floor((Math.min(width, height) / 2 - 12) * Math.SQRT2) : 0
  if (side) roundCanvas = { width, height, side }
  return {
    paper,
    slow: !fast,
    width: side || width,
    height: side || height,
    // Around the page: the desk it lies on.
    desk: ink ? '#ffffff' : '#3a3f4b',
    deskClass: ink ? 'bg-white text-black' : 'bg-[#3a3f4b] text-[#e8eaf0]',
    deskMuted: ink ? 'text-black' : 'text-[#b9bfcc]',
    edge: ink ? '#000000' : null,
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    press: !fast ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#2c3550]',
    line: ink ? 'border-b-2 border-black' : 'border-b border-[#1f2635]',
    bar: ink ? '#000000' : '#3b82f6',
  }
}

const Chevron = ({ size, left }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" d={left ? 'M15 5L8 12L15 19' : 'M9 5L16 12L9 19'} />
  </svg>
)

const DocGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" d="M6 2.5h8l5 5V21a.5.5 0 0 1-.5.5h-12A.5.5 0 0 1 6 21Z M14 2.5V8h5 M9 12.5h6 M9 16h6" />
  </svg>
)

const ListGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="currentColor" d="M4 5h3v3H4ZM9 5.5h11v2H9ZM4 10.5h3v3H4ZM9 11h11v2H9ZM4 16h3v3H4ZM9 16.5h11v2H9Z" />
  </svg>
)

const Refresh = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" d="M19 12a7 7 0 1 1-2.05-4.95M19 4v4h-4" />
  </svg>
)

// Whole page / fit width: the glyph shows what a tap gives.
const FitGlyph = ({ size, width }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      d={width ? 'M7 3h10v18H7Z M3 9l2 3l-2 3 M21 9l-2 3l2 3' : 'M8 4h8v16H8Z M4 2v20 M20 2v20'}
    />
  </svg>
)

// ---- The page ---------------------------------------------------------------------------

const sameClip = (a, b) => a === b || (a && b && a[0] === b[0] && a[1] === b[1] && a[2] === b[2] && a[3] === b[3])

// The page's display list as SVG elements, its pictures decoded from the
// file at the size they cover.
function pageElements(key, ops, ui) {
  const at = placeOf(key)
  const out = []
  let group = null
  let clip = null
  const flush = () => {
    if (!group) return
    if (clip) {
      const w = clip[2] - clip[0]
      const h = clip[3] - clip[1]
      if (w > 0 && h > 0) out.push(<svg x={clip[0]} y={clip[1]} width={w} height={h} viewBox={`${clip[0]} ${clip[1]} ${w} ${h}`}>{group}</svg>)
    } else out.push(...group)
    group = null
  }
  for (const op of ops) {
    let el = null
    if (op.t === 'path') {
      el = (
        <path
          d={op.d}
          fill={op.fill || 'none'}
          fillRule={op.evenOdd ? 'evenodd' : undefined}
          fillOpacity={op.fillOpacity}
          stroke={op.stroke}
          strokeWidth={op.stroke ? op.width : undefined}
          strokeLinecap={op.cap}
          strokeLinejoin={op.join}
          strokeDasharray={op.dash}
          strokeOpacity={op.strokeOpacity}
        />
      )
    } else if (op.t === 'text') {
      el = (
        <text
          x="0"
          y="0"
          fontSize={op.size}
          fill={op.fill}
          stroke={op.bold ? op.fill : undefined}
          strokeWidth={op.bold ? Math.max(0.4, Math.round(op.size * 4) / 100) : undefined}
          opacity={op.opacity < 1 ? op.opacity : undefined}
          transform={`matrix(${op.m.join(' ')})`}
        >
          {op.text}
        </text>
      )
    } else if (op.t === 'image') {
      const src = op.src
      const sw = src.pixels ? src.pixels.width : src.width || op.pw
      const sh = src.pixels ? src.pixels.height : src.height || op.ph
      // As many pixels as it covers, never more than it has, in its own shape.
      let w = Math.max(1, Math.min(op.pw, sw || op.pw, Math.round(ui.width * 1.5)))
      let h = Math.max(1, Math.round(sw && sh ? (w * sh) / sw : op.ph))
      if (h > ui.height * 3) {
        h = Math.round(ui.height * 3)
        w = Math.max(1, Math.round(sw && sh ? (h * sw) / sh : op.pw))
      }
      let ref = null
      try {
        ref = frameos.loadAssetImage(at.path, {
          storage: at.storage,
          offset: src.offset,
          length: src.length,
          inflate: src.inflate === true,
          pixels: src.pixels,
          mask: src.mask,
          width: w,
          height: h,
          fit: 'contain',
          background: '#ffffff',
        })
      } catch (e) {
        ref = null
      }
      if (ref) {
        el = op.m ? (
          <image href={ref} x="0" y="0" width="1" height="1" preserveAspectRatio="none" transform={`matrix(${op.m.join(' ')})`} />
        ) : (
          <image href={ref} x={op.x} y={op.y} width={op.w} height={op.h} preserveAspectRatio="none" />
        )
      } else {
        el = <path d={`M${op.x} ${op.y}h${op.w}v${op.h}h${-op.w}Z`} fill="#e6e6e6" stroke="#b0b0b0" strokeWidth="1" />
      }
    }
    if (!el) continue
    const c = op.clip && !(op.clip[0] <= 0 && op.clip[1] <= 0 && op.clip[2] >= ui.width && op.clip[3] >= ui.height) ? op.clip : null
    if (!group || !sameClip(c, clip)) {
      flush()
      group = []
      clip = c
    }
    group.push(el)
  }
  flush()
  return out
}

function Reader({ ui, spot, entry, save }) {
  const view = viewOf(ui)
  const place = entry.place
  const pages = opened.pages
  const go = (by) => go_(spot, save, { cmds: (spot.cmds || []).concat(by > 0 ? 'next' : 'prev') })
  const tool = `flex items-center justify-center shrink-0 h-[${px(32)}] min-w-[${px(36)}] px-[${px(8)}] rounded-[${px(8)}] text-[${px(14)}] ${ui.soft} ${ui.press}`
  const pageW = drawn.size ? drawn.size.width * place.scale : 0
  const pageH = drawn.size ? drawn.size.height * place.scale : 0
  const top = partY(place, view, entry.part)
  const progress = pages > 0 ? Math.round(((entry.page + (entry.part + 1) / place.parts) / pages) * ui.width) : 0
  const outline = outlineOf(opened)
  const label = `Page ${entry.page + 1} of ${pages}${place.parts > 1 ? ` · ${entry.part + 1}/${place.parts}` : ''}`
  return (
    <div className={`relative w-full h-full ${ui.deskClass}`}>
      <svg className={`absolute left-0 top-[${raw(view.top)}]`} width={view.width} height={view.height} viewBox={`0 0 ${view.width} ${view.height}`}>
        <path d={`M0 0H${view.width}V${view.height}H0Z`} fill={ui.desk} />
        {drawn.size ? (
          <path
            d={`M${Math.round(place.x)} ${Math.round(top)}h${Math.round(pageW)}v${Math.round(pageH)}h${-Math.round(pageW)}Z`}
            fill="#ffffff"
            stroke={ui.edge || undefined}
            strokeWidth={ui.edge ? 1 : undefined}
          />
        ) : null}
        {pageElements(spot.doc, drawn.ops, { width: view.width, height: view.height })}
      </svg>
      <div
        className={`absolute left-0 right-0 top-[${raw(view.top)}] h-[${raw(view.height)}] flex`}
        onSwipe={(e) => {
          if (e.direction === 'left' || e.direction === 'up') go(1)
          else if (e.direction === 'right' || e.direction === 'down') go(-1)
        }}
      >
        <div className="w-1/3 h-full" onClick={() => go(-1)} />
        <div className="flex-1 h-full" onClick={() => go(1)} />
      </div>
      <div className={`absolute left-0 right-0 top-0 flex items-center gap-[${px(8)}] h-[${raw(view.bar)}] px-[${px(8)}] ${ui.bg} ${ui.text}`}>
        <div look="button" className={tool} onClick={() => go_(spot, save, { view: 'library' })}>
          <DocGlyph size={18} />
        </div>
        <span className={`flex-1 min-w-0 truncate text-[${px(14)}]`}>{opened.title}</span>
        <div look="button" className={tool} onClick={() => go_(spot, save, { view: 'goto', typed: '' })}>
          {`${entry.page + 1} / ${pages}`}
        </div>
        <div look="button" className={tool} onClick={() => go_(spot, save, { fit: place.byWidth ? 'page' : 'width' })}>
          <FitGlyph size={18} width={!place.byWidth} />
        </div>
        {outline.length > 0 ? (
          <div look="button" className={tool} onClick={() => go_(spot, save, { view: 'contents', tocPage: null, sel: -1 })}>
            <ListGlyph size={18} />
          </div>
        ) : null}
      </div>
      <div className={`absolute left-0 right-0 bottom-0 flex items-center justify-between gap-[${px(8)}] h-[${raw(view.foot)}] px-[${px(10)}] text-[${px(12)}] ${ui.bg} ${ui.muted}`}>
        <span className="whitespace-nowrap">{label}</span>
        {drawn.problems.length > 0 ? <span className="min-w-0 truncate">{`Not drawn: ${drawn.problems[0]}`}</span> : null}
      </div>
      {progress > 0 ? <div className={`absolute left-0 bottom-0 w-[${raw(progress)}] h-[${raw(Math.max(2, 3 * zoom))}] bg-[${ui.bar}]`} /> : null}
    </div>
  )
}

function go_(spot, save, change) {
  Object.assign(spot, change)
  spot.keys = false
  save(spot)
}

// The page's display list for where the reader is, kept while it stays.
function drawPage(spot, entry, ui) {
  const view = viewOf(ui)
  const doc = opened.doc
  const page = doc.page(entry.page)
  const size = pageSize(doc, page)
  const place = placement(size, view, spot.fit)
  entry.part = Math.max(0, Math.min(entry.part, place.parts - 1))
  const key = `${spot.doc}|${entry.page}|${entry.part}|${place.scale.toFixed(4)}|${view.width}x${view.height}`
  if (drawn.key !== key) {
    drawn = { key: '', ops: [], problems: [], size }
    const out = renderPage(doc, entry.page, { scale: place.scale, x: place.x, y: partY(place, view, entry.part), width: view.width, height: view.height })
    drawn = { key, ops: out.ops, problems: out.problems, size }
  }
  entry.place = place
  return place
}

// A page (or part) forward or back.
function turn(spot, entry, by, ui) {
  const place = drawPage(spot, entry, ui)
  if (by > 0) {
    if (entry.part + 1 < place.parts) entry.part++
    else if (entry.page + 1 < opened.pages) {
      entry.page++
      entry.part = 0
    }
  } else if (entry.part > 0) entry.part--
  else if (entry.page > 0) {
    entry.page--
    // The last part of the page before.
    const size = pageSize(opened.doc, opened.doc.page(entry.page))
    entry.part = placement(size, viewOf(ui), spot.fit).parts - 1
  }
}

// ---- The library ---------------------------------------------------------------

function docsIn(folder, storages, fresh) {
  const where = `${folder}|${storages.map((s) => s.id).join(',')}`
  if (!fresh && listed.folder === where && Date.now() - listed.at < LIST_MS) return listed.docs
  const kept = fresh ? null : frameos.recall('library')
  if (kept && typeof kept === 'object' && kept.folder === where && Date.now() - kept.at < LIST_MS && Array.isArray(kept.docs)) {
    listed = kept
    return listed.docs
  }
  const docs = []
  for (const storage of storages) {
    for (const path of frameos.listAssets(folder, { storage: storage.id }) || []) {
      if (/\.pdf$/i.test(path) && !/(^|\/)\._/.test(path)) docs.push(keyOf(storage.id, path))
    }
  }
  listed = { folder: where, at: Date.now(), docs }
  frameos.remember('library', listed)
  return docs
}

// A document's title and length, read once and kept in the spot (`shelf`).
function metaOf(key, spot) {
  const shelf = spot.shelf && typeof spot.shelf === 'object' ? spot.shelf : (spot.shelf = {})
  let meta = shelf[key]
  if (!meta || typeof meta !== 'object' || typeof meta.title !== 'string') {
    const doc = openDoc(key)
    meta = doc.error ? { title: docName(key), error: doc.error } : { title: doc.title, author: doc.author || '', n: doc.pages }
    shelf[key] = meta
  }
  return meta
}

// Where a document was left, for the library and the next open; the ones
// read longest ago are forgotten first.
function keepPlace(spot, key, entry, meta) {
  const docs = spot.docs && typeof spot.docs === 'object' ? spot.docs : {}
  docs[key] = { page: entry.page, part: entry.part, n: meta.n, t: Date.now(), title: meta.title }
  const keys = Object.keys(docs).sort((a, b) => (docs[b].t || 0) - (docs[a].t || 0))
  for (const k of keys.slice(DOCS_KEPT)) delete docs[k]
  spot.docs = docs
}

function paginate(rows, room) {
  const pages = [[]]
  let used = 0
  rows.forEach((row, i) => {
    const next = rows[i + 1]
    const need = row.header && next ? row.height + next.height : row.height
    if (used + need > room && pages[pages.length - 1].length > 0) {
      pages.push([])
      used = 0
    }
    pages[pages.length - 1].push(row)
    used += row.height
  })
  return pages
}

const pageOf = (pages, index) => Math.max(0, pages.findIndex((page) => page.some((row) => row.index === index)))
const listRoom = (ui) => ui.height / zoom - 56 - 46

// A paged list (the library, the contents): rows, headings among them, arrows,
// and a highlight the keys move. A row's `index` is what onOpen gets.
function Listing({ ui, title, pages: pageRows, page, sel, keys, onPage, onOpen, actions, empty }) {
  const pages = Math.max(1, pageRows.length)
  const shown = pageRows[page] || []
  const rows = pageRows.flat()
  const arrow = `flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${ui.soft} ${ui.press}`
  return (
    <div look="page" className={`flex flex-col w-full h-full ${ui.bg} ${ui.text}`}>
      <div look="bar" className={`flex items-center gap-[${px(10)}] h-[${px(56)}] px-[${px(16)}] shrink-0`}>
        {title}
        {actions}
      </div>
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-hidden px-[${px(16)}]`}
        onSwipe={(e) => {
          if (e.direction === 'left' || e.direction === 'up') onPage(1)
          else if (e.direction === 'right' || e.direction === 'down') onPage(-1)
        }}
      >
        {rows.length === 0 ? (
          <div look="muted" className={`flex flex-col items-center justify-center flex-1 gap-[${px(10)}] px-[${px(24)}] ${ui.muted}`}>
            <DocGlyph size={48} />
            <span className={`text-[${px(16)}] text-center`}>{empty}</span>
          </div>
        ) : (
          shown.map((row) => {
            if (row.header) {
              return (
                <div look="muted" className={`flex items-end h-[${px(row.height)}] px-[${px(10)}] pb-[${px(5)}] shrink-0 text-[${px(13)}] font-bold ${ui.muted}`}>
                  {row.label}
                </div>
              )
            }
            const lit = keys && row.index === sel
            return (
              <div
                look={lit ? 'selected' : 'option'}
                className={`flex items-center gap-[${px(12)}] h-[${px(row.height)}] px-[${px(10)}] shrink-0 ${ui.line} ${lit ? ui.accent : ui.press}`}
                onClick={() => onOpen(row.index)}
              >
                {row.icon ? <DocGlyph size={26} /> : null}
                <div className={`flex flex-col justify-center gap-[${px(2)}] flex-1 min-w-0 pl-[${px(row.indent || 0)}]`}>
                  <span className={`text-[${px(row.sub ? 17 : 16)}] ${row.bold ? 'font-bold' : ''} truncate`}>{row.label}</span>
                  {row.sub ? (
                    <span look="muted" className={`text-[${px(13)}] ${lit ? '' : ui.muted} truncate`}>
                      {row.sub}
                    </span>
                  ) : null}
                </div>
                {row.right ? (
                  <span look="muted" className={`text-[${px(13)}] ${lit ? '' : ui.muted} shrink-0`}>
                    {row.right}
                  </span>
                ) : null}
              </div>
            )
          })
        )}
      </div>
      <div className={`flex items-center justify-end gap-[${px(6)}] h-[${px(46)}] px-[${px(16)}] shrink-0`}>
        {pages > 1
          ? [
              page > 0 ? (
                <div look="button" className={arrow} onClick={() => onPage(-1)}>
                  <Chevron size={18} left />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
              <span look="muted" className={`w-[${px(72)}] text-center text-[${px(13)}] ${ui.muted}`}>{`${page + 1} of ${pages}`}</span>,
              page < pages - 1 ? (
                <div look="button" className={arrow} onClick={() => onPage(1)}>
                  <Chevron size={18} />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
            ]
          : null}
      </div>
    </div>
  )
}

// Go to a page by its number: a keypad.
function GoTo({ ui, spot, save, pages, current, onGo }) {
  const typed = typeof spot.typed === 'string' ? spot.typed : ''
  const number = parseInt(typed, 10)
  const valid = number >= 1 && number <= pages
  const key = `flex items-center justify-center flex-1 h-[${px(48)}] rounded-[${px(10)}] text-[${px(20)}] ${ui.soft} ${ui.press}`
  const type = (d) => go_(spot, save, { typed: (typed + d).replace(/^0+/, '').slice(0, String(pages).length) })
  const row = (digits) => (
    <div className={`flex gap-[${px(8)}] w-full`}>
      {digits.map((d) => (
        <div look="button" className={key} onClick={() => type(d)}>
          {d}
        </div>
      ))}
    </div>
  )
  return (
    <div look="page" className={`flex flex-col w-full h-full ${ui.bg} ${ui.text}`}>
      <div look="bar" className={`flex items-center gap-[${px(10)}] h-[${px(56)}] px-[${px(16)}] shrink-0`}>
        <div look="button" className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`} onClick={() => go_(spot, save, { view: 'doc' })}>
          <Chevron size={20} left />
        </div>
        <div className="flex flex-col flex-1 min-w-0">
          <span className={`text-[${px(19)}] font-bold truncate`}>Go to page</span>
          <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
            {`Page ${current + 1} of ${pages}`}
          </span>
        </div>
      </div>
      <div className={`flex flex-col items-center flex-1 min-h-0 gap-[${px(8)}] px-[${px(16)}] pb-[${px(12)}]`}>
        <div className={`flex items-center justify-center w-full h-[${px(48)}] text-[${px(28)}] font-bold`}>{typed || '–'}</div>
        <div className={`flex flex-col gap-[${px(8)}] w-full max-w-[${px(360)}] flex-1 min-h-0 justify-center`}>
          {row(['1', '2', '3'])}
          {row(['4', '5', '6'])}
          {row(['7', '8', '9'])}
          <div className={`flex gap-[${px(8)}] w-full`}>
            <div look="button" className={key} onClick={() => go_(spot, save, { typed: typed.slice(0, -1) })}>
              <svg viewBox="0 0 24 24" className={`w-[${px(24)}] h-[${px(24)}]`}>
                <path fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" d="M9 5h11v14H9l-6-7Z M12 9l5 6 M17 9l-5 6" />
              </svg>
            </div>
            <div look="button" className={key} onClick={() => type('0')}>
              0
            </div>
            <div look={valid ? 'primary' : 'button'} className={`${key} ${valid ? ui.accent : ''}`} onClick={() => valid && onGo(number - 1)}>
              Go
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export function onEvent(app, context) {
  const p = context.payload || {}
  const event = context.event
  let cmd = null
  if (event === 'button') {
    if (p.action !== 'press') return false
    const label = String(p.label || '').toUpperCase()
    if (label === 'DOWN' || label === 'RIGHT' || label === 'NEXT') cmd = 'next'
    else if (label === 'UP' || label === 'LEFT' || label === 'PREV' || label === 'PREVIOUS') cmd = 'prev'
    else cmd = 'select'
  } else if (event === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return false
    const key = p.key
    if (key === 'ArrowRight' || key === 'ArrowDown' || key === 'PageDown' || key === ' ') cmd = 'next'
    else if (key === 'ArrowLeft' || key === 'ArrowUp' || key === 'PageUp') cmd = 'prev'
    else if (key === 'Enter') cmd = 'select'
    else if (key === 'Escape' || key === 'Backspace') cmd = 'back'
    else if (/^[0-9]$/.test(key)) cmd = `digit${key}`
  } else if (event === 'forward') cmd = 'next'
  else if (event === 'back') cmd = 'prev'
  if (!cmd) return false
  const spot = readSpot(app)
  // Queued: two keys before a render are two keys.
  spot.cmds = (Array.isArray(spot.cmds) ? spot.cmds : []).concat(cmd).slice(-16)
  spot.keys = true
  saveSpot(spot)
  return true
}

// The round panel's canvas when the scene draws one (see uiOf), and whether
// what get() drew is a page on the desk (the desk's colour fills the circle).
let roundCanvas = null
let onDesk = false

export function get(app, context) {
  roundCanvas = null
  onDesk = false
  const drawn = draw(app, context)
  if (!roundCanvas) return drawn
  const { width, height, side } = roundCanvas
  const ui = uiOf(app, context)
  return (
    <div className={`relative w-[${width}px] h-[${height}px] ${onDesk ? ui.deskClass : ui.bg}`}>
      <div className={`absolute left-[${(width - side) >> 1}px] top-[${(height - side) >> 1}px] w-[${side}px] h-[${side}px]`}>{drawn}</div>
    </div>
  )
}

function draw(app, context) {
  const ui = uiOf(app, context)
  const spot = readSpot(app)
  const save = (next) => saveSpot(next)
  spot.view = ['doc', 'contents', 'goto'].includes(spot.view) ? spot.view : 'library'
  spot.fit = spot.fit === 'page' || spot.fit === 'width' ? spot.fit : 'auto'
  // The keys and buttons since the last render, in order.
  const cmds = (Array.isArray(spot.cmds) ? spot.cmds : []).concat(spot.cmd ? [spot.cmd] : [])
  delete spot.cmds
  delete spot.cmd
  const folder = typeof app.state.folder === 'string' ? app.state.folder.trim().replace(/^\/+|\/+$/g, '') : ''
  const storages = storagesOf(app)
  const kept = spot.docs && typeof spot.docs === 'object' ? spot.docs : {}

  // A document another scene opened here (the Files app), where it was left.
  const handed = typeof app.state.file === 'string' ? app.state.file.trim() : ''
  if (handed) {
    frameos.setState('file', '')
    const at = placeOf(handed)
    const key = `${at.storage}:${at.path}`
    const doc = openDoc(key)
    if (doc.error) {
      spot.view = 'library'
      spot.problem = `${docName(key)}: ${doc.error}`
    } else {
      spot.doc = key
      spot.view = 'doc'
      spot.problem = ''
    }
  }

  // The library's documents, the one read last first.
  let docs = null
  const shelf = () => {
    if (docs) return docs
    const fresh = spot.refresh === true
    delete spot.refresh
    if (fresh) {
      spot.shelf = {}
      opened = null
    }
    const order = storages.map((s) => s.id)
    docs = docsIn(folder, storages, fresh)
      .slice()
      .sort((a, b) => {
        const sa = order.indexOf(placeOf(a).storage)
        const sb = order.indexOf(placeOf(b).storage)
        const ta = (kept[a] && kept[a].t) || 0
        const tb = (kept[b] && kept[b].t) || 0
        return sa - sb || tb - ta || docName(a).toLowerCase().localeCompare(docName(b).toLowerCase())
      })
    return docs
  }
  // Opens the library's document i where it was left.
  const open = (i) => {
    const key = shelf()[i]
    if (!key) return
    const doc = openDoc(key)
    if (doc.error) {
      spot.problem = `${docName(key)}: ${doc.error}`
      return
    }
    spot.doc = key
    spot.view = 'doc'
    spot.problem = ''
    spot.sel = i
  }
  // The open document, where it was left, or null (back to the library).
  const current = () => {
    if (!spot.doc) return null
    const doc = openDoc(spot.doc)
    if (doc.error) {
      spot.problem = `${docName(spot.doc)}: ${doc.error}`
      return null
    }
    const left = spot.docs && typeof spot.docs === 'object' ? spot.docs[spot.doc] : null
    const entry = {
      page: left && Number.isInteger(left.page) ? Math.max(0, Math.min(left.page, doc.pages - 1)) : 0,
      part: left && Number.isInteger(left.part) ? Math.max(0, left.part) : 0,
    }
    return { doc, entry, meta: { title: doc.title, n: doc.pages } }
  }
  const jump = (now, page) => {
    now.entry.page = Math.max(0, Math.min(now.doc.pages - 1, page))
    now.entry.part = 0
    spot.view = 'doc'
    spot.typed = ''
    keepPlace(spot, spot.doc, now.entry, now.meta)
  }
  const toLibrary = () => {
    spot.view = 'library'
    spot.sel = Math.max(0, shelf().indexOf(spot.doc))
    spot.page = null
  }

  // Each key or button, as the view it reaches has it.
  for (const cmd of cmds) {
    if (spot.view === 'library') {
      const list = shelf()
      if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = 0
      if (cmd === 'next') spot.sel = Math.min(Math.max(0, list.length - 1), spot.sel + 1)
      else if (cmd === 'prev') spot.sel = Math.max(0, spot.sel - 1)
      else if (cmd === 'select' && list.length > 0) open(Math.max(0, Math.min(spot.sel, list.length - 1)))
      else if (cmd === 'back' && spot.doc) spot.view = 'doc'
      spot.page = null
      continue
    }
    const now = current()
    if (!now) {
      spot.view = 'library'
      continue
    }
    if (spot.view === 'contents') {
      const outline = outlineOf(now.doc)
      if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = 0
      if (cmd === 'next') spot.sel = Math.min(outline.length - 1, spot.sel + 1)
      else if (cmd === 'prev') spot.sel = Math.max(0, spot.sel - 1)
      else if (cmd === 'select' && outline[spot.sel]) jump(now, outline[spot.sel].page)
      else if (cmd === 'back') spot.view = 'doc'
      spot.tocPage = null
    } else if (spot.view === 'goto') {
      const typed = typeof spot.typed === 'string' ? spot.typed : ''
      const number = parseInt(typed, 10)
      if (cmd.startsWith('digit')) spot.typed = (typed + cmd.slice(5)).replace(/^0+/, '').slice(0, String(now.doc.pages).length)
      else if (cmd === 'select' && number >= 1 && number <= now.doc.pages) jump(now, number - 1)
      else if (cmd === 'back') {
        if (typed) spot.typed = typed.slice(0, -1)
        else spot.view = 'doc'
      }
    } else if (cmd === 'next' || cmd === 'prev') {
      turn(spot, now.entry, cmd === 'next' ? 1 : -1, ui)
      keepPlace(spot, spot.doc, now.entry, now.meta)
    } else if (cmd.startsWith('digit')) {
      spot.view = 'goto'
      spot.typed = cmd.slice(5).replace(/^0+/, '')
    } else toLibrary()
  }

  // A document open: its pages, its contents, or the keypad.
  const now = spot.view !== 'library' ? current() : null
  if (now) {
    const { doc, entry, meta } = now
    if (spot.view === 'doc') {
      try {
        drawPage(spot, entry, ui)
      } catch (e) {
        drawn = { key: '', ops: [], problems: [e && e.message ? e.message : 'this page could not be read'], size: null }
        entry.place = { scale: 1, x: 0, y: 0, parts: 1, byWidth: false, step: 0 }
      }
      keepPlace(spot, spot.doc, entry, meta)
      save(spot)
      onDesk = true
      return <Reader ui={ui} spot={spot} entry={entry} save={save} />
    }
    keepPlace(spot, spot.doc, entry, meta)
    if (spot.view === 'goto') {
      save(spot)
      return (
        <GoTo
          ui={ui}
          spot={spot}
          save={save}
          pages={doc.pages}
          current={entry.page}
          onGo={(page) => {
            jump(now, page)
            spot.keys = false
            save(spot)
          }}
        />
      )
    }
    // The contents: the bookmarks, the one the page is under in bold.
    const outline = outlineOf(doc)
    let here = 0
    outline.forEach((item, i) => {
      if (item.page <= entry.page) here = i
    })
    if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = here
    spot.sel = Math.max(0, Math.min(spot.sel, outline.length - 1))
    const pages = paginate(
      outline.map((item, i) => ({ label: item.title, bold: i === here, index: i, height: 46, indent: Math.min(3, item.depth) * 16, right: String(item.page + 1) })),
      listRoom(ui)
    )
    if (typeof spot.tocPage !== 'number') spot.tocPage = pageOf(pages, spot.sel)
    spot.tocPage = Math.max(0, Math.min(spot.tocPage, pages.length - 1))
    save(spot)
    const button = `flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`
    return (
      <Listing
        ui={ui}
        title={[
          <div look="button" className={button} onClick={() => go_(spot, save, { view: 'doc' })}>
            <Chevron size={20} left />
          </div>,
          <div className="flex flex-col flex-1 min-w-0">
            <span className={`text-[${px(19)}] font-bold truncate`}>Contents</span>
            <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
              {doc.title}
            </span>
          </div>,
        ]}
        pages={pages}
        page={spot.tocPage}
        sel={spot.sel}
        keys={spot.keys === true}
        onPage={(by) => go_(spot, save, { tocPage: spot.tocPage + by })}
        onOpen={(i) => {
          if (!outline[i]) return
          jump(now, outline[i].page)
          spot.keys = false
          save(spot)
        }}
        empty="This PDF has no bookmarks."
      />
    )
  }

  // The library: the documents of each storage under its name, when there are two.
  spot.view = 'library'
  const list = shelf()
  if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = 0
  spot.sel = Math.min(spot.sel, Math.max(0, list.length - 1))
  const rows = []
  list.forEach((key, i) => {
    const storage = placeOf(key).storage
    if (storages.length > 1 && (i === 0 || placeOf(list[i - 1]).storage !== storage)) {
      const named = storages.find((s) => s.id === storage)
      rows.push({ header: true, label: named ? named.name : storage, index: -1, height: 34 })
    }
    rows.push({ key, index: i, height: 60 })
  })
  const pages = paginate(rows, listRoom(ui))
  if (typeof spot.page !== 'number') spot.page = pageOf(pages, spot.sel)
  spot.page = Math.max(0, Math.min(spot.page, pages.length - 1))
  // What the shelf keeps of documents no longer listed goes.
  if (spot.shelf && typeof spot.shelf === 'object') {
    for (const key of Object.keys(spot.shelf)) if (!list.includes(key)) delete spot.shelf[key]
  }
  // Titles and lengths for the page showing (the shelf keeps them).
  const showing = new Set((pages[spot.page] || []).filter((row) => !row.header).map((row) => row.key))
  for (const row of rows) {
    if (row.header) continue
    const place = kept[row.key]
    const meta = showing.has(row.key) ? metaOf(row.key, spot) : place && place.title ? { title: place.title, n: place.n } : { title: docName(row.key) }
    const where = place && meta.n ? `Page ${place.page + 1} of ${meta.n}` : meta.error ? meta.error : meta.n ? `${meta.n} page${meta.n === 1 ? '' : 's'}` : ''
    row.label = meta.title
    row.sub = [meta.author, where].filter(Boolean).join(' · ')
    row.bold = row.key === spot.doc
    row.icon = true
  }
  // Saved after the shelf took what was read for this page.
  save(spot)
  const button = `flex items-center justify-center gap-[${px(6)}] h-[${px(40)}] px-[${px(12)}] rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`
  const wide = ui.width / zoom >= 560
  const names = storages.map((s) => (s.id === 'assets' && s.name === 'TF card' ? 'the TF card' : s.name.toLowerCase().replace(/^internal/, 'the internal')))
  const where = `${folder ? `the folder "${folder}" on ` : ''}${names.join(' or ')}`
  return (
    <Listing
      ui={ui}
      title={[
        <div look="accent" className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.accent}`}>
          <DocGlyph size={22} />
        </div>,
        <div className="flex flex-col flex-1 min-w-0">
          <span className={`text-[${px(20)}] font-bold truncate`}>PDF viewer</span>
          {spot.problem ? (
            <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
              {spot.problem}
            </span>
          ) : wide && list.length > 0 ? (
            <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
              {`${list.length} document${list.length === 1 ? '' : 's'}`}
            </span>
          ) : null}
        </div>,
      ]}
      actions={[
        spot.doc && kept[spot.doc] ? (
          <div look="primary" className={`${button} ${ui.accent}`} onClick={() => go_(spot, save, { view: 'doc' })}>
            <span className={`text-[${px(14)}] font-bold`}>{wide ? 'Continue reading' : 'Continue'}</span>
          </div>
        ) : null,
        <div look="button" className={button} onClick={() => go_(spot, save, { refresh: true, problem: '' })}>
          <Refresh size={20} />
        </div>,
      ]}
      pages={pages}
      page={spot.page}
      sel={spot.sel}
      keys={spot.keys === true}
      onPage={(by) => go_(spot, save, { page: spot.page + by })}
      onOpen={(i) => {
        open(i)
        spot.keys = false
        save(spot)
      }}
      empty={`No PDFs yet. Put .pdf files on ${where} and they show up here.`}
    />
  )
}

