// A PDF reader small enough for a frame: the file's cross-reference table
// (or stream) says where each object is, and only the objects a page needs
// are read, a window at a time. A page's content streams become a display
// list in the screen's pixels: paths, words and pictures, each where the
// page puts it. The frame inflates FlateDecode streams itself
// (frameos.readAsset { inflate }) and decodes pictures straight from the file
// (frameos.loadAssetImage { offset, length, pixels }), so a page never holds
// more than its own streams.
//
// Text is drawn in the frame's face, each run stretched to the width the
// PDF's own font gives it, so lines, columns and tables stand where the page
// has them. Embedded font programs are not drawn; nor are shadings (a mean
// colour instead), soft masks, blend modes and non-rectangular clips.
//
// io: { size, read(offset, length) -> Uint8Array, inflate(offset, length) -> Uint8Array | null }

const MAX_WINDOW = 4 * 1024 * 1024

class More extends Error {}
class PdfError extends Error {}

// ---- Bytes -------------------------------------------------------------------

const WHITE = new Uint8Array(256)
for (const c of [0, 9, 10, 12, 13, 32]) WHITE[c] = 1
const DELIM = new Uint8Array(256)
for (const c of '()<>[]{}/%') DELIM[c.charCodeAt(0)] = 1
const isRegular = (c) => !WHITE[c] && !DELIM[c]

function latin1(bytes, from = 0, to = bytes.length) {
  let out = ''
  for (let i = from; i < to; i += 8192) out += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(to, i + 8192)))
  return out
}

function concat(parts) {
  let n = 0
  for (const p of parts) n += p.length
  const out = new Uint8Array(n)
  let at = 0
  for (const p of parts) {
    out.set(p, at)
    at += p.length
  }
  return out
}

// ---- Objects -----------------------------------------------------------------

// Names are JS strings; a PDF string is { s } (its bytes as a latin1 string);
// a reference { r, g }; a keyword (in content streams) { k }.
const ref = (r, g) => ({ r, g })
const isRef = (v) => v !== null && typeof v === 'object' && typeof v.r === 'number'
const isStr = (v) => v !== null && typeof v === 'object' && typeof v.s === 'string'
const isDict = (v) => v !== null && typeof v === 'object' && !Array.isArray(v) && !isRef(v) && !isStr(v) && !v.k && !v.stream
const isStream = (v) => v !== null && typeof v === 'object' && v.stream === true

class Lexer {
  constructor(bytes, pos = 0, whole = true) {
    this.b = bytes
    this.p = pos
    this.whole = whole // true: the end of the bytes is the end of the data
  }
  end() {
    if (!this.whole) throw new More()
    return true
  }
  ws() {
    const b = this.b
    for (;;) {
      while (this.p < b.length && WHITE[b[this.p]]) this.p++
      if (this.p < b.length && b[this.p] === 37) {
        while (this.p < b.length && b[this.p] !== 10 && b[this.p] !== 13) this.p++
        continue
      }
      if (this.p >= b.length) this.end()
      return
    }
  }
  word() {
    const b = this.b
    const start = this.p
    while (this.p < b.length && isRegular(b[this.p])) this.p++
    if (this.p >= b.length && !this.whole) throw new More()
    return latin1(b, start, this.p)
  }
  // The next object; a keyword comes back as { k } (null at the end).
  obj(refs = true) {
    this.ws()
    const b = this.b
    if (this.p >= b.length) return null
    const c = b[this.p]
    if (c === 47) {
      this.p++
      const w = this.word()
      return w.indexOf('#') < 0 ? w : w.replace(/#([0-9a-fA-F]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    }
    if (c === 60) {
      if (b[this.p + 1] === 60) {
        this.p += 2
        const d = Object.create(null)
        for (;;) {
          this.ws()
          if (b[this.p] === 62 && b[this.p + 1] === 62) {
            this.p += 2
            return d
          }
          if (this.p >= b.length) return d
          const key = this.obj(false)
          if (typeof key !== 'string') {
            if (key && key.k) continue // junk in a damaged dictionary
            return d
          }
          d[key] = this.obj()
        }
      }
      this.p++
      let hex = ''
      while (this.p < b.length && b[this.p] !== 62) {
        if (!WHITE[b[this.p]]) hex += String.fromCharCode(b[this.p])
        this.p++
      }
      if (this.p >= b.length) this.end()
      this.p++
      if (hex.length % 2) hex += '0'
      let s = ''
      for (let i = 0; i < hex.length; i += 2) s += String.fromCharCode(parseInt(hex.substr(i, 2), 16) || 0)
      return { s }
    }
    if (c === 91) {
      this.p++
      const a = []
      for (;;) {
        this.ws()
        if (this.p >= b.length) return a
        if (b[this.p] === 93) {
          this.p++
          return a
        }
        a.push(this.obj())
      }
    }
    if (c === 40) return this.literal()
    if ((c >= 48 && c <= 57) || c === 43 || c === 45 || c === 46) {
      const n = this.number()
      if (refs && Number.isInteger(n) && n >= 0) {
        // "n g R" is a reference; a window that ends inside one is read
        // again bigger (More goes up).
        const save = this.p
        this.ws()
        const d = b[this.p]
        if (d >= 48 && d <= 57) {
          const g = this.number()
          this.ws()
          if (b[this.p] === 82 && (this.p + 1 >= b.length || !isRegular(b[this.p + 1]))) {
            this.p++
            return ref(n, g)
          }
        }
        this.p = save
      }
      return n
    }
    if (c === 41 || c === 62 || c === 93 || c === 125 || c === 123) {
      this.p++
      return { k: String.fromCharCode(c) }
    }
    const w = this.word()
    if (w === 'true') return true
    if (w === 'false') return false
    if (w === 'null') return null
    if (!w) {
      this.p++
      return { k: '' }
    }
    return { k: w }
  }
  number() {
    const b = this.b
    const start = this.p
    if (b[this.p] === 43 || b[this.p] === 45) this.p++
    while (this.p < b.length && ((b[this.p] >= 48 && b[this.p] <= 57) || b[this.p] === 46)) this.p++
    if (this.p >= b.length && !this.whole) throw new More()
    // "4.-2" and "--3" happen in the wild: read what makes a number.
    const n = parseFloat(latin1(b, start, this.p))
    return Number.isFinite(n) ? n : 0
  }
  literal() {
    const b = this.b
    this.p++
    let depth = 1
    const out = []
    while (this.p < b.length) {
      let c = b[this.p++]
      if (c === 40) depth++
      else if (c === 41) {
        if (--depth === 0) return { s: String.fromCharCode.apply(null, out.length > 60000 ? out.slice(0, 60000) : out) }
      } else if (c === 92) {
        c = b[this.p++]
        if (c === 110) c = 10
        else if (c === 114) c = 13
        else if (c === 116) c = 9
        else if (c === 98) c = 8
        else if (c === 102) c = 12
        else if (c >= 48 && c <= 55) {
          let v = c - 48
          for (let i = 0; i < 2 && b[this.p] >= 48 && b[this.p] <= 55; i++) v = v * 8 + b[this.p++] - 48
          c = v & 255
        } else if (c === 13) {
          if (b[this.p] === 10) this.p++
          continue
        } else if (c === 10) continue
      }
      out.push(c)
    }
    this.end()
    return { s: String.fromCharCode.apply(null, out) }
  }
}

// ---- Filters done in JavaScript ----------------------------------------------

function unpredict(data, parms) {
  const predictor = (parms && parms.Predictor) || 1
  if (predictor < 2) return data
  const colors = (parms && parms.Colors) || 1
  const bpc = (parms && parms.BitsPerComponent) || 8
  const columns = (parms && parms.Columns) || 1
  const rowBytes = Math.ceil((colors * bpc * columns) / 8)
  const bpp = Math.max(1, Math.ceil((colors * bpc) / 8))
  if (predictor === 2) {
    const out = data.slice()
    if (bpc !== 8) return out
    for (let r = 0; r + rowBytes <= out.length; r += rowBytes)
      for (let i = bpp; i < rowBytes; i++) out[r + i] = (out[r + i] + out[r + i - bpp]) & 255
    return out
  }
  const rows = Math.floor(data.length / (rowBytes + 1))
  const out = new Uint8Array(rows * rowBytes)
  let prev = new Uint8Array(rowBytes)
  for (let r = 0; r < rows; r++) {
    const kind = data[r * (rowBytes + 1)]
    const src = r * (rowBytes + 1) + 1
    const dst = r * rowBytes
    for (let i = 0; i < rowBytes; i++) {
      const left = i >= bpp ? out[dst + i - bpp] : 0
      const up = prev[i]
      const ul = i >= bpp ? prev[i - bpp] : 0
      let v = data[src + i]
      if (kind === 1) v += left
      else if (kind === 2) v += up
      else if (kind === 3) v += (left + up) >> 1
      else if (kind === 4) {
        const p = left + up - ul
        const pa = Math.abs(p - left)
        const pb = Math.abs(p - up)
        const pc = Math.abs(p - ul)
        v += pa <= pb && pa <= pc ? left : pb <= pc ? up : ul
      }
      out[dst + i] = v & 255
    }
    prev = out.subarray(dst, dst + rowBytes)
  }
  return out
}

function asciiHex(data) {
  const out = []
  let hi = -1
  for (const c of data) {
    if (c === 62) break
    const v = c >= 48 && c <= 57 ? c - 48 : c >= 65 && c <= 70 ? c - 55 : c >= 97 && c <= 102 ? c - 87 : -1
    if (v < 0) continue
    if (hi < 0) hi = v
    else {
      out.push(hi * 16 + v)
      hi = -1
    }
  }
  if (hi >= 0) out.push(hi * 16)
  return Uint8Array.from(out)
}

function ascii85(data) {
  const out = []
  let group = []
  for (let i = 0; i < data.length; i++) {
    const c = data[i]
    if (c === 126) break
    if (c === 122 && group.length === 0) {
      out.push(0, 0, 0, 0)
      continue
    }
    if (c < 33 || c > 117) continue
    group.push(c - 33)
    if (group.length === 5) {
      let v = 0
      for (const g of group) v = v * 85 + g
      out.push((v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255)
      group = []
    }
  }
  if (group.length > 1) {
    const n = group.length
    while (group.length < 5) group.push(84)
    let v = 0
    for (const g of group) v = v * 85 + g
    const bytes = [(v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255]
    for (let i = 0; i < n - 1; i++) out.push(bytes[i])
  }
  return Uint8Array.from(out)
}

function lzw(data, parms) {
  const early = parms && parms.EarlyChange === 0 ? 0 : 1
  const out = []
  let dict = []
  const reset = () => {
    dict = []
    for (let i = 0; i < 256; i++) dict.push([i])
    dict.push(null, null)
  }
  reset()
  let bits = 9
  let buf = 0
  let nbits = 0
  let prev = null
  for (let i = 0; i < data.length; i++) {
    buf = (buf << 8) | data[i]
    nbits += 8
    while (nbits >= bits) {
      const code = (buf >>> (nbits - bits)) & ((1 << bits) - 1)
      nbits -= bits
      buf &= (1 << nbits) - 1
      if (code === 256) {
        reset()
        bits = 9
        prev = null
        continue
      }
      if (code === 257) return Uint8Array.from(out)
      let entry = dict[code]
      if (!entry && prev) entry = prev.concat(prev[0])
      if (!entry) return Uint8Array.from(out)
      for (const v of entry) out.push(v)
      if (prev) dict.push(prev.concat(entry[0]))
      prev = entry
      const size = dict.length + early
      bits = size >= 2048 ? 12 : size >= 1024 ? 11 : size >= 512 ? 10 : 9
    }
  }
  return Uint8Array.from(unpredict(Uint8Array.from(out), parms))
}

function runLength(data) {
  const out = []
  for (let i = 0; i < data.length; ) {
    const n = data[i++]
    if (n === 128) break
    if (n < 128) for (let k = 0; k <= n && i < data.length; k++) out.push(data[i++])
    else {
      const v = data[i++]
      for (let k = 0; k < 257 - n; k++) out.push(v)
    }
  }
  return Uint8Array.from(out)
}

const FILTER_NAMES = {
  Fl: 'FlateDecode', AHx: 'ASCIIHexDecode', A85: 'ASCII85Decode', LZW: 'LZWDecode',
  RL: 'RunLengthDecode', DCT: 'DCTDecode', CCF: 'CCITTFaxDecode'
}
const listOf = (v) => (v === undefined || v === null ? [] : Array.isArray(v) ? v : [v])

// ---- The document ------------------------------------------------------------

export class PdfDocument {
  constructor(io) {
    this.io = io
    this.size = io.size
    this.offsets = [] // object number -> file offset
    this.inStream = [] // object number -> [object stream number, index]
    this.cache = new Map()
    this.objStms = new Map()
    this.trailer = Object.create(null)
    this.fonts = new Map()
    this.pages = new Map()
    this.open()
  }

  read(offset, length) {
    const n = Math.max(0, Math.min(length, this.size - offset))
    if (n <= 0) return new Uint8Array(0)
    const bytes = this.io.read(offset, n)
    if (!bytes) throw new PdfError('could not read the file')
    return bytes
  }

  open() {
    if (this.size < 32) throw new PdfError('not a PDF')
    const head = latin1(this.read(0, 1024))
    const at = head.indexOf('%PDF-')
    if (at < 0) throw new PdfError('not a PDF')
    this.base = at // some files carry junk before the header
    let ok = false
    try {
      const tail = latin1(this.read(Math.max(0, this.size - 2048), 2048))
      const sx = tail.lastIndexOf('startxref')
      if (sx >= 0) {
        const m = /startxref\s+(\d+)/.exec(tail.slice(sx))
        if (m) {
          let pos = parseInt(m[1], 10)
          const seen = new Set()
          while (pos >= 0 && pos < this.size && !seen.has(pos)) {
            seen.add(pos)
            pos = this.readXref(pos)
          }
          ok = !!this.trailer.Root
        }
      }
    } catch (e) {
      if (e instanceof PdfError) throw e
      ok = false
    }
    if (ok) {
      try {
        this.catalog = this.get(this.trailer.Root)
        ok = isDict(this.catalog) && !!this.catalog.Pages
      } catch (e) {
        ok = false
      }
    }
    if (!ok) {
      this.rebuild()
      this.catalog = this.trailer.Root ? this.get(this.trailer.Root) : null
      // A file cut short can lose its catalog or its page tree (both often
      // at the end): its pages are then the page objects it still has.
      const pages = isDict(this.catalog) ? this.get(this.catalog.Pages) : null
      if (!isDict(pages) || !(pages.Count > 0)) {
        const kids = this.scanPages()
        if (kids.length === 0) throw new PdfError('this PDF is damaged')
        this.catalog = Object.assign(Object.create(null), isDict(this.catalog) ? this.catalog : {}, {
          Pages: { Type: 'Pages', Kids: kids, Count: kids.length },
        })
      }
    }
    if (!isDict(this.catalog)) throw new PdfError('this PDF is damaged')
    if (this.trailer.Encrypt) throw new PdfError('this PDF is encrypted')
  }

  // One cross-reference section at pos: a table or a stream. Returns the
  // previous section's position, or -1.
  readXref(pos) {
    const bytes = this.read(pos, 64)
    if (latin1(bytes, 0, 4) === 'xref') return this.readXrefTable(pos)
    // An xref stream: an object whose dictionary says /Type /XRef.
    const obj = this.readObjectAt(pos)
    if (!isStream(obj) || obj.dict.Type !== 'XRef') throw new Error('bad xref')
    const dict = obj.dict
    this.mergeTrailer(dict)
    const w = dict.W
    const data = this.streamBytes(obj)
    const size = dict.Size || 0
    const index = Array.isArray(dict.Index) ? dict.Index : [0, size]
    const rowLen = w[0] + w[1] + w[2]
    let at = 0
    const field = (n) => {
      let v = 0
      for (let i = 0; i < n; i++) v = v * 256 + data[at++]
      return v
    }
    for (let s = 0; s + 1 < index.length; s += 2) {
      const first = index[s]
      const count = index[s + 1]
      for (let i = 0; i < count && at + rowLen <= data.length; i++) {
        const type = w[0] ? field(w[0]) : 1
        const a = field(w[1])
        const b = field(w[2])
        const num = first + i
        if (this.offsets[num] !== undefined || this.inStream[num] !== undefined) continue
        if (type === 1) this.offsets[num] = a + 0
        else if (type === 2) this.inStream[num] = [a, b]
        else if (type === 0) this.offsets[num] = -1
      }
    }
    if (typeof dict.XRefStm === 'number') this.readXref(dict.XRefStm)
    return typeof dict.Prev === 'number' ? dict.Prev : -1
  }

  readXrefTable(pos) {
    let window = 64 * 1024
    for (;;) {
      const bytes = this.read(pos, window)
      const whole = pos + bytes.length >= this.size
      const L = new Lexer(bytes, 4, whole)
      try {
        const entries = []
        for (;;) {
          L.ws()
          const first = L.obj(false)
          if (first && first.k === 'trailer') break
          if (typeof first !== 'number') throw new Error('bad xref table')
          const count = L.obj(false)
          L.ws()
          for (let i = 0; i < count; i++) {
            // 20-byte entries, but some writers use 19 or 21: read tokens.
            const off = L.obj(false)
            const gen = L.obj(false)
            const kind = L.obj(false)
            entries.push([first + i, off, kind && kind.k])
          }
        }
        const trailer = L.obj()
        for (const [num, off, kind] of entries) {
          if (this.offsets[num] !== undefined || this.inStream[num] !== undefined) continue
          this.offsets[num] = kind === 'n' ? off : -1
        }
        if (!isDict(trailer)) throw new Error('bad trailer')
        this.mergeTrailer(trailer)
        if (typeof trailer.XRefStm === 'number') {
          try {
            this.readXref(trailer.XRefStm)
          } catch (e) {}
        }
        return typeof trailer.Prev === 'number' ? trailer.Prev : -1
      } catch (e) {
        if (e instanceof More && window < MAX_WINDOW) {
          window *= 4
          continue
        }
        throw e
      }
    }
  }

  mergeTrailer(dict) {
    for (const key of ['Root', 'Info', 'Encrypt', 'ID']) if (this.trailer[key] === undefined && dict[key] !== undefined) this.trailer[key] = dict[key]
  }

  // A file whose cross-references are missing or wrong: every "n g obj" in
  // it, read front to back.
  rebuild() {
    this.offsets = []
    this.inStream = []
    this.cache.clear()
    const chunk = 256 * 1024
    let roots = []
    for (let pos = 0; pos < this.size; pos += chunk - 64) {
      const text = latin1(this.read(pos, chunk))
      const re = /(\d+)\s+(\d+)\s+obj\b/g
      let m
      while ((m = re.exec(text))) {
        const at = pos + m.index
        // An object number glued to the end of the line before is not one.
        if (m.index > 0 && /\d/.test(text[m.index - 1])) continue
        this.offsets[parseInt(m[1], 10)] = at
      }
      let t = text.indexOf('trailer')
      while (t >= 0) {
        roots.push(pos + t)
        t = text.indexOf('trailer', t + 7)
      }
      if (pos + chunk >= this.size) break
    }
    for (const at of roots) {
      try {
        const L = new Lexer(this.read(at + 7, 4096), 0, true)
        const d = L.obj()
        if (isDict(d) && d.Root) this.mergeTrailer(d)
      } catch (e) {}
    }
    if (!this.trailer.Root) {
      // No trailer (cross-reference streams): the catalog itself.
      for (let num = 0; num < this.offsets.length; num++) {
        if (this.offsets[num] === undefined) continue
        try {
          const o = this.readObjectAt(this.offsets[num])
          const d = isStream(o) ? o.dict : o
          if (isDict(d) && d.Type === 'XRef') {
            this.mergeTrailer(d)
            if (d.Root) break
          }
          if (isDict(d) && d.Type === 'Catalog') {
            this.trailer.Root = ref(num, 0)
            break
          }
        } catch (e) {}
      }
    }
    for (let num = 0; num < this.offsets.length; num++) {
      if (this.offsets[num] === undefined) continue
      try {
        const o = this.readObjectAt(this.offsets[num])
        if (isStream(o) && o.dict.Type === 'ObjStm') {
          const { ids } = this.objStm(num)
          ids.forEach((id, i) => {
            if (this.offsets[id] === undefined && this.inStream[id] === undefined) this.inStream[id] = [num, i]
          })
        }
      } catch (e) {}
    }
    if (!this.trailer.Root) {
      for (let num = 0; num < this.inStream.length; num++) {
        if (!this.inStream[num]) continue
        try {
          const d = this.get(ref(num, 0))
          if (isDict(d) && d.Type === 'Catalog') {
            this.trailer.Root = ref(num, 0)
            break
          }
        } catch (e) {}
      }
    }
  }

  // Every page object in the file, in the order they are in it.
  scanPages() {
    const found = []
    this.offsets.forEach((off, num) => {
      if (off === undefined || off < 0) return
      const d = this.get(ref(num, 0))
      if (isDict(d) && d.Type === 'Page') found.push([off, num])
    })
    this.inStream.forEach((at, num) => {
      if (!at) return
      const d = this.get(ref(num, 0))
      if (isDict(d) && d.Type === 'Page') found.push([this.offsets[at[0]] + at[1] / 1e6, num])
    })
    found.sort((a, b) => a[0] - b[0])
    return found.map(([, num]) => ref(num, 0))
  }

  // The object at a file offset: "n g obj ... endobj", a stream's data left
  // in the file ({ stream, dict, start, length }).
  readObjectAt(pos) {
    let window = 4096
    for (;;) {
      const bytes = this.read(pos, window)
      const whole = pos + bytes.length >= this.size
      const L = new Lexer(bytes, 0, whole)
      try {
        L.obj(false)
        L.obj(false)
        const kw = L.obj(false)
        if (!kw || kw.k !== 'obj') throw new Error('no object here')
        const value = L.obj()
        if (!isDict(value)) return value
        const save = L.p
        let next = null
        try {
          next = L.obj(false)
        } catch (e) {
          if (!(e instanceof More)) throw e
          if (whole) next = null
          else throw e
        }
        if (!next || next.k !== 'stream') {
          L.p = save
          return value
        }
        // The data starts after the end of the line.
        if (L.b[L.p] === 13) L.p++
        if (L.b[L.p] === 10) L.p++
        const start = pos + L.p
        let length = value.Length
        if (isRef(length)) length = this.get(length)
        if (typeof length !== 'number' || length < 0 || !this.endsAt(start + length)) length = this.findEnd(start)
        return { stream: true, dict: value, start, length }
      } catch (e) {
        if (e instanceof More && window < MAX_WINDOW) {
          window *= 4
          continue
        }
        throw e
      }
    }
  }

  endsAt(at) {
    const text = latin1(this.read(at, 24))
    return /^\s*endstream/.test(text) || /^\s*endobj/.test(text)
  }

  findEnd(start) {
    for (let pos = start; pos < this.size; pos += 65536 - 16) {
      const text = latin1(this.read(pos, 65536))
      const at = text.indexOf('endstream')
      if (at >= 0) {
        let end = pos + at
        // The end of line before endstream is not data.
        const before = this.read(Math.max(start, end - 2), Math.min(2, end - start))
        if (before[before.length - 1] === 10) end--
        if (before.length === 2 && before[0] === 13 && before[1] === 10) end--
        else if (before[before.length - 1] === 13) end--
        return Math.max(0, end - start)
      }
    }
    return Math.max(0, this.size - start)
  }

  objStm(num) {
    let entry = this.objStms.get(num)
    if (entry) return entry
    const stream = this.get(ref(num, 0))
    if (!isStream(stream)) throw new Error('not an object stream')
    const data = this.streamBytes(stream)
    const n = stream.dict.N || 0
    const first = stream.dict.First || 0
    const L = new Lexer(data, 0, true)
    const ids = []
    const offs = []
    for (let i = 0; i < n; i++) {
      ids.push(L.obj(false))
      offs.push(L.obj(false))
    }
    entry = { data, first, ids, offs }
    if (this.objStms.size >= 3) this.objStms.delete(this.objStms.keys().next().value)
    this.objStms.set(num, entry)
    return entry
  }

  // A reference resolved (anything else as it is).
  get(v) {
    if (!isRef(v)) return v
    const num = v.r
    if (this.cache.has(num)) return this.cache.get(num)
    this.cache.set(num, null) // a loop of references ends in null
    let value = null
    try {
      const off = this.offsets[num]
      if (off !== undefined && off >= 0) value = this.readObjectAt(off + (off < this.base ? this.base : 0))
      else if (this.inStream[num]) {
        const [stm, index] = this.inStream[num]
        const entry = this.objStm(stm)
        const L = new Lexer(entry.data, entry.first + entry.offs[index], true)
        value = L.obj()
      }
    } catch (e) {
      value = null
    }
    if (this.cache.size > 4000) this.cache.clear()
    this.cache.set(num, value)
    return value
  }

  // A stream's data, decoded: FlateDecode by the frame, the rest here.
  streamBytes(stream) {
    const dict = stream.dict
    const filters = listOf(this.get(dict.Filter)).map((f) => FILTER_NAMES[f] || f)
    const parms = listOf(this.get(dict.DecodeParms)).map((p) => this.get(p))
    let data = null
    let i = 0
    if (filters[0] === 'FlateDecode') {
      data = this.io.inflate(stream.start, stream.length)
      if (!data) throw new PdfError('a stream is too big for this frame')
      data = unpredict(data, parms[0])
      i = 1
    } else data = this.read(stream.start, stream.length)
    for (; i < filters.length; i++) {
      const f = filters[i]
      const p = parms[i]
      if (f === 'ASCIIHexDecode') data = asciiHex(data)
      else if (f === 'ASCII85Decode') data = ascii85(data)
      else if (f === 'LZWDecode') data = lzw(data, p)
      else if (f === 'RunLengthDecode') data = runLength(data)
      else throw new PdfError(`${f} after another filter is not supported`)
    }
    return data
  }

  // Each of a page's content streams, joined.
  contentBytes(contents) {
    const parts = []
    for (const c of listOf(this.get(contents))) {
      const s = this.get(c)
      if (!isStream(s)) continue
      try {
        parts.push(this.streamBytes(s), Uint8Array.of(10))
      } catch (e) {
        if (e instanceof PdfError) throw e
      }
    }
    return concat(parts)
  }

  get pageCount() {
    if (this._count === undefined) {
      const pages = this.get(this.catalog.Pages)
      this._count = isDict(pages) && typeof pages.Count === 'number' ? pages.Count : 0
      if (!this._count) this._count = this.pageRefs().length
    }
    return this._count
  }

  // Page i (from 0): its dictionary with what it inherits from the tree.
  page(index) {
    let page = this.pages.get(index)
    if (!page) {
      page = this.findPage(index)
      if (this.pages.size > 64) this.pages.clear()
      this.pages.set(index, page)
    }
    return page
  }

  findPage(index) {
    let node = this.get(this.catalog.Pages)
    const inherited = Object.create(null)
    let i = index
    for (let depth = 0; depth < 32 && isDict(node); depth++) {
      for (const key of ['Resources', 'MediaBox', 'CropBox', 'Rotate']) if (node[key] !== undefined) inherited[key] = node[key]
      if (node.Type === 'Page' || (!node.Kids && node.Contents !== undefined)) return { dict: node, ...inherited }
      const kids = this.get(node.Kids)
      if (!Array.isArray(kids)) break
      let next = null
      for (const kid of kids) {
        const k = this.get(kid)
        if (!isDict(k)) continue
        const isPages = k.Type === 'Pages' || (k.Kids && k.Type !== 'Page')
        const count = isPages ? (typeof k.Count === 'number' ? k.Count : 1) : 1
        if (i < count) {
          next = k
          break
        }
        i -= count
      }
      if (!next) break
      node = next
    }
    // A tree whose counts are wrong: the leaves in order.
    const refs = this.pageRefs()
    const d = this.get(refs[index])
    if (!isDict(d)) throw new PdfError('no such page')
    return { dict: d, Resources: d.Resources, MediaBox: d.MediaBox, CropBox: d.CropBox, Rotate: d.Rotate }
  }

  // Every page's reference, in order (outlines name pages by reference).
  pageRefs() {
    if (this._refs) return this._refs
    const out = []
    const walk = (v, depth) => {
      if (depth > 32 || out.length > 20000) return
      const node = this.get(v)
      if (!isDict(node)) return
      const kids = this.get(node.Kids)
      if (Array.isArray(kids) && node.Type !== 'Page') for (const kid of kids) walk(kid, depth + 1)
      else out.push(v)
    }
    walk(this.catalog.Pages, 0)
    this._refs = out
    return out
  }

  info() {
    const info = this.get(this.trailer.Info)
    return {
      title: isDict(info) ? textOf(this.get(info.Title)).trim() : '',
      author: isDict(info) ? textOf(this.get(info.Author)).trim() : '',
    }
  }

  // The bookmarks: [{ title, page, depth }].
  outline(maxItems = 500) {
    const outlines = this.get(this.catalog.Outlines)
    if (!isDict(outlines)) return []
    const refs = this.pageRefs()
    const pageOf = new Map(refs.map((r, i) => [isRef(r) ? r.r : -1, i]))
    const items = []
    const seen = new Set()
    const walk = (v, depth) => {
      let cur = v
      while (cur && items.length < maxItems) {
        if (isRef(cur)) {
          if (seen.has(cur.r)) return
          seen.add(cur.r)
        }
        const item = this.get(cur)
        if (!isDict(item)) return
        const page = this.destPage(item, pageOf)
        const title = textOf(this.get(item.Title)).replace(/\s+/g, ' ').trim()
        if (title) items.push({ title, page, depth })
        if (item.First && depth < 4) walk(item.First, depth + 1)
        cur = item.Next
      }
    }
    walk(outlines.First, 0)
    return items
  }

  destPage(item, pageOf) {
    let dest = this.get(item.Dest)
    const action = this.get(item.A)
    if (dest === undefined && isDict(action) && action.S === 'GoTo') dest = this.get(action.D)
    if (isStr(dest) || typeof dest === 'string') dest = this.named(isStr(dest) ? dest.s : dest)
    dest = this.get(dest)
    if (isDict(dest)) dest = this.get(dest.D)
    if (!Array.isArray(dest) || dest.length === 0) return -1
    const target = dest[0]
    if (isRef(target)) return pageOf.has(target.r) ? pageOf.get(target.r) : -1
    return typeof target === 'number' ? target : -1
  }

  named(name) {
    const old = this.get(this.catalog.Dests)
    if (isDict(old) && old[name] !== undefined) return old[name]
    const names = this.get(this.catalog.Names)
    const tree = isDict(names) ? this.get(names.Dests) : null
    const look = (v, depth) => {
      const node = this.get(v)
      if (!isDict(node) || depth > 16) return undefined
      const limits = this.get(node.Limits)
      if (Array.isArray(limits) && limits.length === 2 && isStr(limits[0]) && isStr(limits[1])) {
        if (name < limits[0].s || name > limits[1].s) return undefined
      }
      const leaf = this.get(node.Names)
      if (Array.isArray(leaf)) {
        for (let i = 0; i + 1 < leaf.length; i += 2) if (isStr(leaf[i]) && leaf[i].s === name) return leaf[i + 1]
      }
      const kids = this.get(node.Kids)
      if (Array.isArray(kids))
        for (const kid of kids) {
          const found = look(kid, depth + 1)
          if (found !== undefined) return found
        }
      return undefined
    }
    return tree ? look(tree, 0) : undefined
  }
}

