function utf16(s, from) {
  let out = ''
  for (let i = from; i + 1 < s.length; i += 2) out += String.fromCharCode((s.charCodeAt(i) << 8) | s.charCodeAt(i + 1))
  return out
}

// A text string (a title, a bookmark): UTF-16 with its mark, UTF-8 with its
// mark, else PDFDocEncoding.
export function textOf(v) {
  if (!isStr(v)) return typeof v === 'string' ? v : ''
  const s = v.s
  if (s.charCodeAt(0) === 0xfe && s.charCodeAt(1) === 0xff) return utf16(s, 2)
  if (s.charCodeAt(0) === 0xef && s.charCodeAt(1) === 0xbb && s.charCodeAt(2) === 0xbf && typeof TextDecoder === 'function') {
    try {
      return new TextDecoder().decode(Uint8Array.from(s.slice(3), (c) => c.charCodeAt(0)))
    } catch (e) {}
  }
  let out = ''
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i)
    out += String.fromCharCode(PDFDOC[c] || c)
  }
  return out
}

