// A ToUnicode CMap: codes to text, and how many bytes a code is.
function parseCMap(bytes) {
  const map = new Map()
  const ranges = []
  const spaces = []
  const L = new Lexer(bytes, 0, true)
  const hexOf = (v) => (isStr(v) ? v.s : '')
  const codeOf = (s) => {
    let v = 0
    for (let i = 0; i < s.length; i++) v = v * 256 + s.charCodeAt(i)
    return v
  }
  const textOfDst = (s) => {
    if (s.length === 1) return s
    return utf16(s, 0)
  }
  const ops = []
  for (let guard = 0; guard < 200000; guard++) {
    const v = L.obj(false)
    if (v === null) break
    if (v && v.k) {
      if (v.k === 'endcodespacerange') {
        for (let i = 0; i + 1 < ops.length; i += 2) spaces.push(hexOf(ops[i]).length)
      } else if (v.k === 'endbfchar') {
        for (let i = 0; i + 1 < ops.length; i += 2) map.set(codeOf(hexOf(ops[i])), isStr(ops[i + 1]) ? textOfDst(ops[i + 1].s) : typeof ops[i + 1] === 'string' ? glyphText(ops[i + 1]) : '')
      } else if (v.k === 'endbfrange') {
        for (let i = 0; i + 2 < ops.length; i += 3) {
          const lo = codeOf(hexOf(ops[i]))
          const hi = codeOf(hexOf(ops[i + 1]))
          const dst = ops[i + 2]
          if (Array.isArray(dst)) {
            for (let c = lo; c <= hi && c - lo < dst.length; c++) map.set(c, isStr(dst[c - lo]) ? textOfDst(dst[c - lo].s) : '')
          } else if (isStr(dst)) {
            if (hi - lo <= 256) {
              const s = dst.s
              for (let c = lo; c <= hi; c++) {
                const last = s.length - 1
                const bumped = s.slice(0, last) + String.fromCharCode(s.charCodeAt(last) + (c - lo))
                map.set(c, textOfDst(bumped))
              }
            } else ranges.push([lo, hi, textOfDst(dst.s)])
          }
        }
      }
      ops.length = 0
    } else ops.push(v)
  }
  return {
    bytes: spaces.length ? Math.min(...spaces) : 0,
    get(code) {
      const t = map.get(code)
      if (t !== undefined) return t
      for (const [lo, hi, s] of ranges) {
        if (code >= lo && code <= hi) {
          const last = s.length - 1
          return s.slice(0, last) + String.fromCharCode(s.charCodeAt(last) + (code - lo))
        }
      }
      return undefined
    },
  }
}

