// A font as the page uses it: how its codes are read, how wide each glyph is
// and the text it stands for. Fonts are drawn in the frame's face.
function makeFont(doc, dict) {
  const subtype = dict.Subtype
  const baseName = (typeof dict.BaseFont === 'string' ? dict.BaseFont : '').replace(/^[A-Z]{6}\+/, '')
  let desc = doc.get(dict.FontDescriptor)
  let cid = null
  if (subtype === 'Type0') {
    const kids = doc.get(dict.DescendantFonts)
    cid = Array.isArray(kids) ? doc.get(kids[0]) : null
    if (isDict(cid)) desc = doc.get(cid.FontDescriptor)
  }
  const flags = isDict(desc) && typeof desc.Flags === 'number' ? desc.Flags : 0
  const weight = isDict(desc) && typeof desc.FontWeight === 'number' ? desc.FontWeight : 0
  const font = {
    bold: /bold|black|heavy|semibold|demi/i.test(baseName) || weight >= 600 || (flags & 0x40000) !== 0,
    italic: /italic|oblique/i.test(baseName) || (flags & 64) !== 0,
    mono: /courier|mono|consol|typewriter|cmtt/i.test(baseName) || (flags & 1) !== 0,
    serif: /times|serif|roman|georgia|garamond|cmr|minion|palatino|book/i.test(baseName) || (flags & 2) !== 0,
    type3: subtype === 'Type3',
    bytes: 1,
    widths: null,
  }
  let toUnicode = null
  const tu = doc.get(dict.ToUnicode)
  if (isStream(tu)) {
    try {
      toUnicode = parseCMap(doc.streamBytes(tu))
    } catch (e) {}
  }
  if (subtype === 'Type0') {
    const enc = doc.get(dict.Encoding)
    font.bytes = 2
    if (isStream(enc)) {
      try {
        const cmap = parseCMap(doc.streamBytes(enc))
        if (cmap.bytes === 1) font.bytes = 1
      } catch (e) {}
    }
    const ucs2 = typeof enc === 'string' && /^Uni.*-(UCS2|UTF16)-/.test(enc)
    const widths = new Map()
    const dw = isDict(cid) && typeof cid.DW === 'number' ? cid.DW : 1000
    const w = isDict(cid) ? doc.get(cid.W) : null
    if (Array.isArray(w)) {
      for (let i = 0; i < w.length; ) {
        const first = doc.get(w[i])
        const next = doc.get(w[i + 1])
        if (Array.isArray(next)) {
          next.forEach((v, k) => widths.set(first + k, doc.get(v)))
          i += 2
        } else {
          const last = next
          const v = doc.get(w[i + 2])
          if (last - first < 65536) for (let c = first; c <= last; c++) widths.set(c, v)
          i += 3
        }
      }
    }
    font.width = (code) => {
      const v = widths.get(code)
      return typeof v === 'number' ? v : dw
    }
    font.text = (code) => {
      if (toUnicode) {
        const t = toUnicode.get(code)
        if (t !== undefined) return t
      }
      return ucs2 ? String.fromCharCode(code) : ''
    }
    return font
  }
  // A simple font: one byte a code.
  const first = typeof dict.FirstChar === 'number' ? dict.FirstChar : 0
  const widths = doc.get(dict.Widths)
  const matrix = font.type3 && Array.isArray(dict.FontMatrix) ? dict.FontMatrix[0] * 1000 : 1
  const missing = isDict(desc) && typeof desc.MissingWidth === 'number' ? desc.MissingWidth : 0
  const std = /courier/i.test(baseName) ? null : /times|serif/i.test(baseName) ? TIMES : HELVETICA
  const stdScale = font.bold ? 1.05 : 1
  font.width = (code) => {
    if (Array.isArray(widths)) {
      const v = doc.get(widths[code - first])
      if (typeof v === 'number') return v * matrix
      return missing
    }
    if (!std) return 600
    return code >= 32 && code <= 126 ? std[code - 32] * stdScale : 556
  }
  let encoding = doc.get(dict.Encoding)
  let baseEnc = typeof encoding === 'string' ? encoding : isDict(encoding) && typeof encoding.BaseEncoding === 'string' ? encoding.BaseEncoding : ''
  const diffs = new Map()
  if (isDict(encoding) && Array.isArray(encoding.Differences)) {
    let code = 0
    for (const v of encoding.Differences) {
      if (typeof v === 'number') code = v
      else if (typeof v === 'string') diffs.set(code++, v)
    }
  }
  const symbolic = /symbol|dingbat/i.test(baseName)
  // An embedded Type 1 program's own encoding, from its clear-text part.
  if (!baseEnc && diffs.size === 0 && !toUnicode && isDict(desc) && isStream(doc.get(desc.FontFile))) {
    try {
      const program = doc.get(desc.FontFile)
      const clear = latin1(doc.streamBytes(program).subarray(0, Math.min(program.dict.Length1 || 65536, 65536)))
      if (!/\/Encoding\s+StandardEncoding/.test(clear)) {
        const re = /dup\s+(\d+)\s*\/([^\s/]+)\s+put/g
        let m
        while ((m = re.exec(clear))) diffs.set(parseInt(m[1], 10), m[2])
      }
    } catch (e) {}
  }
  if (!baseEnc) baseEnc = subtype === 'TrueType' ? 'WinAnsiEncoding' : 'StandardEncoding'
  font.text = (code) => {
    if (toUnicode) {
      const t = toUnicode.get(code)
      if (t !== undefined) return t
    }
    if (diffs.has(code)) {
      const t = glyphText(diffs.get(code))
      if (t) return t
      if (/^(g|cid|G)\d+$|^[a-z]\d+$/.test(diffs.get(code))) return ''
    }
    if (symbolic) return code === 183 || code === 108 ? '•' : code >= 32 && code < 127 && /symbol/i.test(baseName) ? '' : ''
    const u = baseEncoding(baseEnc, code)
    return u ? String.fromCharCode(u) : ''
  }
  return font
}

// ---- Colours -----------------------------------------------------------------

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v)
const hex2 = (v) => {
  const n = Math.round(clamp01(v) * 255)
  return (n < 16 ? '0' : '') + n.toString(16)
}
const rgbHex = (r, g, b) => `#${hex2(r)}${hex2(g)}${hex2(b)}`
const cmyk = (c, m, y, k) => [(1 - c) * (1 - k), (1 - m) * (1 - k), (1 - y) * (1 - k)]

// A type 2 (exponential) function, what most spot colours and shadings use;
// anything else is read as a grey of its first input.
function evalFunction(doc, fn, t) {
  const f = doc.get(fn)
  const d = isStream(f) ? f.dict : f
  if (isDict(d) && d.FunctionType === 2) {
    const c0 = Array.isArray(d.C0) ? d.C0 : [0]
    const c1 = Array.isArray(d.C1) ? d.C1 : [1]
    const n = typeof d.N === 'number' ? d.N : 1
    const x = Math.pow(clamp01(t), n)
    return c0.map((v, i) => v + x * ((c1[i] === undefined ? 1 : c1[i]) - v))
  }
  if (isDict(d) && d.FunctionType === 3 && Array.isArray(d.Functions)) {
    const fns = d.Functions
    return evalFunction(doc, fns[Math.min(fns.length - 1, Math.floor(clamp01(t) * fns.length))], t)
  }
  return null
}

// A colour space: how many components, and how they become RGB.
function colorSpace(doc, cs, resources, depth = 0) {
  let v = doc.get(cs)
  if (typeof v === 'string' && !['DeviceGray', 'DeviceRGB', 'DeviceCMYK', 'G', 'RGB', 'CMYK', 'Pattern'].includes(v)) {
    const named = isDict(resources) ? doc.get(resources.ColorSpace) : null
    if (isDict(named) && named[v] !== undefined && depth < 4) return colorSpace(doc, named[v], resources, depth + 1)
  }
  const name = Array.isArray(v) ? doc.get(v[0]) : v
  if (name === 'DeviceGray' || name === 'G' || name === 'CalGray') return { n: 1, rgb: (c) => [c[0], c[0], c[0]] }
  if (name === 'DeviceRGB' || name === 'RGB' || name === 'CalRGB') return { n: 3, rgb: (c) => [c[0], c[1], c[2]] }
  if (name === 'DeviceCMYK' || name === 'CMYK') return { n: 4, rgb: (c) => cmyk(c[0], c[1], c[2], c[3]) }
  if (name === 'Lab') return { n: 3, rgb: (c) => [c[0] / 100, c[0] / 100, c[0] / 100] }
  if (name === 'ICCBased') {
    const s = doc.get(v[1])
    const n = isStream(s) && typeof s.dict.N === 'number' ? s.dict.N : 3
    return n === 1 ? colorSpace(doc, 'DeviceGray') : n === 4 ? colorSpace(doc, 'DeviceCMYK') : colorSpace(doc, 'DeviceRGB')
  }
  if (name === 'Indexed' || name === 'I') {
    const base = colorSpace(doc, v[1], resources, depth + 1)
    const hival = doc.get(v[2]) || 0
    let lookup = doc.get(v[3])
    let bytes = ''
    if (isStr(lookup)) bytes = lookup.s
    else if (isStream(lookup)) bytes = latin1(doc.streamBytes(lookup))
    return {
      n: 1,
      indexed: true,
      base,
      hival,
      lookup: bytes,
      rgb: (c) => {
        const i = Math.max(0, Math.min(hival, Math.round(c[0])))
        const comps = []
        for (let k = 0; k < base.n; k++) comps.push(bytes.charCodeAt(i * base.n + k) / 255)
        return base.rgb(comps)
      },
    }
  }
  if (name === 'Separation' || name === 'DeviceN') {
    const n = name === 'Separation' ? 1 : Array.isArray(doc.get(v[1])) ? doc.get(v[1]).length : 1
    const alt = colorSpace(doc, v[2], resources, depth + 1)
    const fn = v[3]
    const sepName = doc.get(v[1])
    return {
      n,
      rgb: (c) => {
        if (sepName === 'None') return null
        const out = evalFunction(doc, fn, c[0])
        if (out && out.length === alt.n) return alt.rgb(out)
        const t = clamp01(c[0])
        return [1 - t, 1 - t, 1 - t]
      },
    }
  }
  if (name === 'Pattern') return { n: 0, pattern: true, rgb: () => [0.8, 0.8, 0.8] }
  return { n: 1, rgb: (c) => [c[0], c[0], c[0]] }
}

// The colour a pattern or shading stands for: the middle of its function.
function shadingColor(doc, shading, resources) {
  const sh = doc.get(shading)
  const d = isStream(sh) ? sh.dict : sh
  if (!isDict(d)) return null
  const cs = colorSpace(doc, d.ColorSpace, resources)
  const fns = doc.get(d.Function)
  let comps = null
  if (Array.isArray(fns)) comps = fns.map((f) => (evalFunction(doc, f, 0.5) || [0.8])[0])
  else if (fns) comps = evalFunction(doc, fns, 0.5)
  if (!comps || comps.length < cs.n) return null
  const rgb = cs.rgb(comps)
  return rgb ? rgbHex(rgb[0], rgb[1], rgb[2]) : null
}

// ---- Pages -------------------------------------------------------------------

const mul = (m, n) => [
  m[0] * n[0] + m[1] * n[2],
  m[0] * n[1] + m[1] * n[3],
  m[2] * n[0] + m[3] * n[2],
  m[2] * n[1] + m[3] * n[3],
  m[4] * n[0] + m[5] * n[2] + n[4],
  m[4] * n[1] + m[5] * n[3] + n[5],
]
const apply = (m, x, y) => [m[0] * x + m[2] * y + m[4], m[1] * x + m[3] * y + m[5]]
const r1 = (v) => Math.round(v * 10) / 10

function boxOf(doc, v) {
  const a = doc.get(v)
  if (!Array.isArray(a) || a.length < 4) return null
  const n = a.map((x) => doc.get(x))
  if (n.some((x) => typeof x !== 'number')) return null
  return [Math.min(n[0], n[2]), Math.min(n[1], n[3]), Math.max(n[0], n[2]), Math.max(n[1], n[3])]
}

// A page's size in points as it is shown (its rotation applied).
export function pageSize(doc, page) {
  const box = boxOf(doc, page.CropBox) || boxOf(doc, page.MediaBox) || [0, 0, 612, 792]
  const media = boxOf(doc, page.MediaBox)
  if (media) {
    box[0] = Math.max(box[0], media[0])
    box[1] = Math.max(box[1], media[1])
    box[2] = Math.min(box[2], media[2])
    box[3] = Math.min(box[3], media[3])
  }
  if (box[2] - box[0] < 1 || box[3] - box[1] < 1) box.splice(0, 4, 0, 0, 612, 792)
  const rotate = ((((doc.get(page.Rotate) || 0) % 360) + 360) % 360) / 90
  const w = box[2] - box[0]
  const h = box[3] - box[1]
  return { box, rotate: Math.round(rotate) % 4, width: rotate % 2 ? h : w, height: rotate % 2 ? w : h }
}

// The page's content as what to draw, in the pixels of a view `view`
// ({ width, height }) where the page is drawn at `scale` pixels a point with
// its top left corner at (x, y): { ops, problems }. Ops are
//   { t: 'path', d, fill, stroke, width, evenOdd, cap, join, dash, opacity, clip }
//   { t: 'text', text, size, m: [a, b, c, d, e, f], fill, bold, italic, mono, opacity, clip }
//   { t: 'image', x, y, w, h, m?, pw, ph, src: { offset, length, inflate, pixels }, clip }
// (an image's m, when it is turned or mirrored, takes its 0..1 box to the
// screen; pw x ph is the size to decode it at)
// where clip is null or [x0, y0, x1, y1].
export function renderPage(doc, index, place) {
  const page = doc.page(index)
  const size = pageSize(doc, page)
  const [x0, y0, x1, y1] = size.box
  const s = place.scale
  const rot = [
    [1, 0, 0, -1, -x0, y1],
    [0, 1, 1, 0, -y0, -x0],
    [-1, 0, 0, 1, x1, -y0],
    [0, -1, -1, 0, y1, x1],
  ][size.rotate]
  const P = mul(rot, [s, 0, 0, s, place.x, place.y])
  const view = [0, 0, place.width, place.height]
  const out = { ops: [], problems: new Set(), size }
  let content
  try {
    content = doc.contentBytes(page.dict.Contents)
  } catch (e) {
    out.problems.add(e.message)
    return out
  }
  const r = new Renderer(doc, out, view)
  r.run(content, page.Resources, P, 0)
  // Form fields and stamps: what each annotation shows.
  try {
    const annots = doc.get(page.dict.Annots)
    if (Array.isArray(annots))
      for (const a of annots.slice(0, 200)) {
        const annot = doc.get(a)
        if (!isDict(annot) || annot.Subtype === 'Popup' || annot.Subtype === 'Link') continue
        const flags = typeof annot.F === 'number' ? annot.F : 0
        if (flags & 2 || flags & 32) continue // hidden, or not for viewing
        const ap = doc.get(annot.AP)
        if (!isDict(ap)) continue
        let normal = doc.get(ap.N)
        if (isDict(normal) && !isStream(normal)) normal = doc.get(normal[annot.AS || 'Off'])
        const rect = boxOf(doc, annot.Rect)
        if (!isStream(normal) || !rect) continue
        const bbox = boxOf(doc, normal.dict.BBox) || rect
        const matrix = Array.isArray(normal.dict.Matrix) ? normal.dict.Matrix.map((v) => doc.get(v)) : [1, 0, 0, 1, 0, 0]
        // The appearance's box, through its matrix, onto the annotation's rectangle.
        const corners = [apply(matrix, bbox[0], bbox[1]), apply(matrix, bbox[2], bbox[3]), apply(matrix, bbox[0], bbox[3]), apply(matrix, bbox[2], bbox[1])]
        const bx0 = Math.min(...corners.map((c) => c[0]))
        const by0 = Math.min(...corners.map((c) => c[1]))
        const bx1 = Math.max(...corners.map((c) => c[0]))
        const by1 = Math.max(...corners.map((c) => c[1]))
        const sx = (rect[2] - rect[0]) / Math.max(0.001, bx1 - bx0)
        const sy = (rect[3] - rect[1]) / Math.max(0.001, by1 - by0)
        const A = [sx, 0, 0, sy, rect[0] - bx0 * sx, rect[1] - by0 * sy]
        r.form(normal, mul(A, P), page.Resources, 1)
      }
  } catch (e) {}
  out.problems = [...out.problems]
  return out
}

class Renderer {
  constructor(doc, out, view) {
    this.doc = doc
    this.out = out
    this.view = view
    this.budget = 400000 // operators a page, a guard against a runaway stream
  }

  problem(text) {
    this.out.problems.add(text)
  }

  font(resources, name) {
    const fonts = isDict(resources) ? this.doc.get(resources.Font) : null
    const v = isDict(fonts) ? fonts[name] : undefined
    const key = isRef(v) ? `r${v.r}` : null
    if (key && this.doc.fonts.has(key)) return this.doc.fonts.get(key)
    const dict = this.doc.get(v)
    let font = null
    if (isDict(dict)) {
      try {
        font = makeFont(this.doc, dict)
      } catch (e) {
        font = null
      }
    }
    if (!font) font = makeFont(this.doc, { Subtype: 'Type1', BaseFont: 'Helvetica' })
    if (key) this.doc.fonts.set(key, font)
    return font
  }

  form(stream, ctm, resources, depth) {
    const dict = stream.dict
    const matrix = Array.isArray(dict.Matrix) ? dict.Matrix.map((v) => this.doc.get(v)) : [1, 0, 0, 1, 0, 0]
    const m = mul(matrix, ctm)
    let clip = null
    const bbox = boxOf(this.doc, dict.BBox)
    if (bbox) clip = rectClip(m, bbox)
    let bytes
    try {
      bytes = this.doc.streamBytes(stream)
    } catch (e) {
      this.problem(e.message)
      return
    }
    this.run(bytes, dict.Resources || resources, m, depth, clip)
  }

  // outer: the graphics state a form starts from (its Do's).
  run(bytes, resources, ctm, depth, clip = null, outer = null) {
    const doc = this.doc
    resources = doc.get(resources)
    const view = this.view
    const ops = this.out.ops
    let gs = outer ? { ...outer, ctm, clip: clip ? intersect(clip, outer.clip) : outer.clip.slice() } : {
      ctm,
      fill: '#000000',
      stroke: '#000000',
      fillCs: colorSpace(doc, 'DeviceGray'),
      strokeCs: colorSpace(doc, 'DeviceGray'),
      lw: 1,
      cap: 0,
      join: 0,
      dash: null,
      fillAlpha: 1,
      strokeAlpha: 1,
      clip: clip ? intersect(clip, view) : view.slice(),
      font: null,
      fs: 12,
      tc: 0,
      tw: 0,
      th: 1,
      tl: 0,
      tr: 0,
      rise: 0,
    }
    const stack = []
    let path = ''
    let pathBox = null
    let rectOnly = null // the path when it is one rectangle in user space
    let segments = 0
    let pendingClip = 0
    let tm = [1, 0, 0, 1, 0, 0]
    let tlm = [1, 0, 0, 1, 0, 0]
    let run = null // the text run being gathered
    let cx = 0
    let cy = 0
    let sx = 0
    let sy = 0

    const grow = (x, y) => {
      if (!pathBox) pathBox = [x, y, x, y]
      else {
        if (x < pathBox[0]) pathBox[0] = x
        if (y < pathBox[1]) pathBox[1] = y
        if (x > pathBox[2]) pathBox[2] = x
        if (y > pathBox[3]) pathBox[3] = y
      }
    }
    const pt = (x, y) => {
      const p = apply(gs.ctm, x, y)
      grow(p[0], p[1])
      return `${r1(p[0])} ${r1(p[1])}`
    }
    const scaleOf = (m) => Math.sqrt(Math.abs(m[0] * m[3] - m[1] * m[2]))
    const visible = (box, clipBox) => box && box[2] >= clipBox[0] && box[0] <= clipBox[2] && box[3] >= clipBox[1] && box[1] <= clipBox[3]
    const color = (cs, operands) => {
      if (cs.pattern) {
        const name = operands[operands.length - 1]
        if (typeof name === 'string') {
          const patterns = isDict(resources) ? doc.get(resources.Pattern) : null
          const pat = isDict(patterns) ? doc.get(patterns[name]) : null
          const pd = isStream(pat) ? pat.dict : pat
          if (isDict(pd) && pd.PatternType === 2) return shadingColor(doc, pd.Shading, resources) || '#cccccc'
          if (isStream(pat) && pd.PaintType === 2 && operands.length > 1) return null // uncoloured tiling: its colour is the operands'
          return '#cccccc'
        }
        return '#cccccc'
      }
      const comps = operands.filter((v) => typeof v === 'number')
      while (comps.length < cs.n) comps.push(0)
      const rgb = cs.rgb(comps)
      return rgb ? rgbHex(rgb[0], rgb[1], rgb[2]) : 'none'
    }

    const flushRun = () => {
      if (!run) return
      const text = run.text.replace(/\s+/g, ' ').trim()
      if (text && visible(run.box, run.clip)) {
        const em = ubuntuEm(text)
        const width = Math.hypot(run.end[0] - run.start[0], run.end[1] - run.start[1])
        let k = em > 0 && width > 0 ? width / (em * run.size) : 1
        if (k < 0.5) k = 0.5
        else if (k > 2) k = 2
        const u = run.u
        const v = run.v
        // An italic face slants: x moves right as the glyph goes up.
        const slant = run.italic ? 0.2 : 0
        ops.push({
          t: 'text',
          text,
          size: r1(run.size),
          m: [u[0] * k, u[1] * k, v[0] - slant * u[0], v[1] - slant * u[1], r1(run.start[0]), r1(run.start[1])].map((n, i) => (i < 4 ? Math.round(n * 1000) / 1000 : n)),
          fill: run.fill,
          bold: run.bold,
          italic: run.italic,
          mono: run.mono,
          serif: run.serif,
          opacity: run.opacity,
          clip: run.clip,
        })
      }
      run = null
    }

    // One glyph shown: where it is, what it says and how far it moves the pen.
    const glyph = (code, font) => {
      const w0 = font.width(code) / 1000
      const fs = gs.fs
      const space = font.bytes === 1 && code === 32 ? gs.tw : 0
      const trm = mul([fs * gs.th, 0, 0, fs, 0, gs.rise], mul(tm, gs.ctm))
      let text = font.text(code)
      if (text && LIGATURES[text] !== undefined) text = LIGATURES[text]
      const adv = (w0 * fs + gs.tc + space) * gs.th
      const own = (w0 * fs + gs.tc) * gs.th
      const origin = [trm[4], trm[5]]
      const endM = mul([1, 0, 0, 1, own, 0], tm)
      const endT = mul([fs * gs.th, 0, 0, fs, 0, gs.rise], mul(endM, gs.ctm))
      const end = [endT[4], endT[5]]
      tm = mul([1, 0, 0, 1, adv, 0], tm)
      if (gs.tr === 3 || gs.tr === 7 || !text) return
      if (/^\s+$/.test(text)) {
        if (run) run.text += ' '
        return
      }
      const size = Math.hypot(trm[2], trm[3])
      if (size < 0.5) return
      const bl = Math.hypot(trm[0], trm[1]) || 1
      const u = [trm[0] / bl, trm[1] / bl]
      const v = [-trm[2] / size, -trm[3] / size]
      if (run) {
        // Joined to the run when it carries on along the same baseline:
        // straight on, or after a gap the size of a space.
        const same = run.font === font && Math.abs(run.size - size) < 0.05 * size && run.fill === gs.fill && Math.abs(run.u[0] - u[0]) < 0.01 && Math.abs(run.u[1] - u[1]) < 0.01
        const dx = origin[0] - run.end[0]
        const dy = origin[1] - run.end[1]
        const along = dx * u[0] + dy * u[1]
        const across = -dx * u[1] + dy * u[0]
        if (same && Math.abs(across) < 0.15 * size && along > -0.25 * size && along < 1.2 * size) {
          if (along > 0.18 * size && !run.text.endsWith(' ')) run.text += ' '
          run.text += text
          run.end = end
          growBox(run.box, origin, end, size)
          return
        }
        flushRun()
      }
      run = {
        font,
        text,
        size,
        start: origin,
        end,
        u,
        v,
        fill: gs.tr === 1 || gs.tr === 5 ? gs.stroke : gs.fill,
        bold: font.bold,
        italic: font.italic,
        mono: font.mono,
        serif: font.serif,
        opacity: gs.fillAlpha,
        clip: gs.clip,
        box: [Math.min(origin[0], end[0]), Math.min(origin[1], end[1]) - size, Math.max(origin[0], end[0]), Math.max(origin[1], end[1]) + size * 0.3],
      }
    }
    const show = (str) => {
      const font = gs.font || (gs.font = this.font(null, ''))
      const s = str.s
      if (font.bytes === 2) for (let i = 0; i + 1 < s.length; i += 2) glyph((s.charCodeAt(i) << 8) | s.charCodeAt(i + 1), font)
      else for (let i = 0; i < s.length; i++) glyph(s.charCodeAt(i), font)
    }

    const paint = (fill, stroke, evenOdd) => {
      if (path && (fill || stroke) && visible(pathBox, gs.clip)) {
        const sw = gs.lw * scaleOf(gs.ctm)
        const op = { t: 'path', d: path, clip: gs.clip }
        if (fill && gs.fill !== 'none' && gs.fill !== null) {
          op.fill = gs.fill
          if (evenOdd) op.evenOdd = true
          if (gs.fillAlpha < 1) op.fillOpacity = gs.fillAlpha
        }
        if (stroke && gs.stroke !== 'none' && gs.stroke !== null) {
          op.stroke = gs.stroke
          op.width = Math.max(0.6, r1(sw))
          if (gs.cap) op.cap = gs.cap === 1 ? 'round' : 'square'
          if (gs.join) op.join = gs.join === 1 ? 'round' : 'bevel'
          if (gs.dash && gs.dash.length) {
            const sc = scaleOf(gs.ctm)
            op.dash = gs.dash.map((d) => Math.max(0.5, r1(d * sc))).join(' ')
          }
          if (gs.strokeAlpha < 1) op.strokeOpacity = gs.strokeAlpha
        }
        if (op.fill || op.stroke) ops.push(op)
      }
      if (pendingClip) {
        const box = rectOnly && segments === 1 ? rectClip(gs.ctm, rectOnly) : null
        if (box) gs.clip = intersect(gs.clip, box)
        else if (pathBox) gs.clip = intersect(gs.clip, pathBox) // the clip's bounds, as near as a rectangle goes
        pendingClip = 0
      }
      path = ''
      pathBox = null
      rectOnly = null
      segments = 0
    }

    const L = new Lexer(bytes, 0, true)
    const args = []
    for (;;) {
      if (--this.budget < 0) {
        this.problem('the page is too long to draw whole')
        break
      }
      let v
      try {
        v = L.obj(false)
      } catch (e) {
        break
      }
      if (v === null) break
      if (!v || !v.k) {
        if (args.length < 64) args.push(v)
        continue
      }
      const op = v.k
      const a = args
      try {
        switch (op) {
          case 'q':
            if (stack.length < 64) stack.push({ ...gs })
            break
          case 'Q':
            if (stack.length) gs = stack.pop()
            break
          case 'cm':
            if (a.length >= 6) gs.ctm = mul(a.slice(-6), gs.ctm)
            break
          case 'w':
            gs.lw = a[0]
            break
          case 'J':
            gs.cap = a[0]
            break
          case 'j':
            gs.join = a[0]
            break
          case 'd':
            gs.dash = Array.isArray(a[0]) && a[0].some((x) => x > 0) ? a[0].filter((x) => typeof x === 'number') : null
            break
          case 'gs': {
            const states = isDict(resources) ? doc.get(resources.ExtGState) : null
            const st = isDict(states) ? doc.get(states[a[0]]) : null
            if (isDict(st)) {
              if (typeof st.LW === 'number') gs.lw = st.LW
              if (typeof st.ca === 'number') gs.fillAlpha = st.ca
              if (typeof st.CA === 'number') gs.strokeAlpha = st.CA
              if (typeof st.LC === 'number') gs.cap = st.LC
              if (typeof st.LJ === 'number') gs.join = st.LJ
              const f = doc.get(st.Font)
              if (Array.isArray(f) && isRef(f[0])) {
                gs.font = this.font({ Font: { _: f[0] } }, '_')
                gs.fs = f[1]
              }
              if (st.SMask && st.SMask !== 'None') this.problem('soft masks are drawn without their mask')
            }
            break
          }
          case 'm':
            if (rectOnly) rectOnly = null
            cx = sx = a[0]
            cy = sy = a[1]
            path += `M${pt(cx, cy)}`
            segments += 2
            break
          case 'l':
            cx = a[0]
            cy = a[1]
            path += `L${pt(cx, cy)}`
            break
          case 'c':
            path += `C${pt(a[0], a[1])} ${pt(a[2], a[3])} ${pt(a[4], a[5])}`
            cx = a[4]
            cy = a[5]
            break
          case 'v':
            path += `C${pt(cx, cy)} ${pt(a[0], a[1])} ${pt(a[2], a[3])}`
            cx = a[2]
            cy = a[3]
            break
          case 'y':
            path += `C${pt(a[0], a[1])} ${pt(a[2], a[3])} ${pt(a[2], a[3])}`
            cx = a[2]
            cy = a[3]
            break
          case 'h':
            path += 'Z'
            cx = sx
            cy = sy
            break
          case 're': {
            const [x, y, w, h] = a
            path += `M${pt(x, y)}L${pt(x + w, y)}L${pt(x + w, y + h)}L${pt(x, y + h)}Z`
            rectOnly = segments === 0 ? [Math.min(x, x + w), Math.min(y, y + h), Math.max(x, x + w), Math.max(y, y + h)] : null
            segments++
            cx = sx = x
            cy = sy = y
            break
          }
          case 'S':
            paint(false, true)
            break
          case 's':
            path += 'Z'
            paint(false, true)
            break
          case 'f':
          case 'F':
            paint(true, false)
            break
          case 'f*':
            paint(true, false, true)
            break
          case 'B':
            paint(true, true)
            break
          case 'B*':
            paint(true, true, true)
            break
          case 'b':
            path += 'Z'
            paint(true, true)
            break
          case 'b*':
            path += 'Z'
            paint(true, true, true)
            break
          case 'n':
            paint(false, false)
            break
          case 'W':
          case 'W*':
            pendingClip = 1
            break
          case 'g':
            gs.fillCs = colorSpace(doc, 'DeviceGray')
            gs.fill = color(gs.fillCs, a)
            break
          case 'G':
            gs.strokeCs = colorSpace(doc, 'DeviceGray')
            gs.stroke = color(gs.strokeCs, a)
            break
          case 'rg':
            gs.fillCs = colorSpace(doc, 'DeviceRGB')
            gs.fill = color(gs.fillCs, a)
            break
          case 'RG':
            gs.strokeCs = colorSpace(doc, 'DeviceRGB')
            gs.stroke = color(gs.strokeCs, a)
            break
          case 'k':
            gs.fillCs = colorSpace(doc, 'DeviceCMYK')
            gs.fill = color(gs.fillCs, a)
            break
          case 'K':
            gs.strokeCs = colorSpace(doc, 'DeviceCMYK')
            gs.stroke = color(gs.strokeCs, a)
            break
          case 'cs':
            gs.fillCs = colorSpace(doc, a[0], resources)
            gs.fill = gs.fillCs.pattern ? '#cccccc' : color(gs.fillCs, [])
            break
          case 'CS':
            gs.strokeCs = colorSpace(doc, a[0], resources)
            gs.stroke = gs.strokeCs.pattern ? '#cccccc' : color(gs.strokeCs, [])
            break
          case 'sc':
          case 'scn': {
            const c = color(gs.fillCs, a)
            if (c !== null) gs.fill = c
            break
          }
          case 'SC':
          case 'SCN': {
            const c = color(gs.strokeCs, a)
            if (c !== null) gs.stroke = c
            break
          }
          case 'sh': {
            // A shading fills the clip: its middle colour, flat.
            const shadings = isDict(resources) ? doc.get(resources.Shading) : null
            const c = isDict(shadings) ? shadingColor(doc, shadings[a[0]], resources) : null
            const box = gs.clip
            if (c && box[2] > box[0] && box[3] > box[1] && (box[2] - box[0]) * (box[3] - box[1]) < view[2] * view[3] * 0.98)
              ops.push({ t: 'path', d: `M${r1(box[0])} ${r1(box[1])}H${r1(box[2])}V${r1(box[3])}H${r1(box[0])}Z`, fill: c, clip: null })
            break
          }
          case 'BT':
            tm = [1, 0, 0, 1, 0, 0]
            tlm = [1, 0, 0, 1, 0, 0]
            break
          case 'ET':
            flushRun()
            break
          case 'Tc':
            gs.tc = a[0]
            break
          case 'Tw':
            gs.tw = a[0]
            break
          case 'Tz':
            gs.th = a[0] / 100
            break
          case 'TL':
            gs.tl = a[0]
            break
          case 'Tr':
            gs.tr = a[0]
            break
          case 'Ts':
            gs.rise = a[0]
            break
          case 'Tf':
            gs.font = this.font(resources, a[0])
            gs.fs = a[1]
            break
          case 'Td':
            tlm = mul([1, 0, 0, 1, a[0], a[1]], tlm)
            tm = tlm.slice()
            break
          case 'TD':
            gs.tl = -a[1]
            tlm = mul([1, 0, 0, 1, a[0], a[1]], tlm)
            tm = tlm.slice()
            break
          case 'Tm':
            tlm = a.slice(-6)
            tm = tlm.slice()
            break
          case 'T*':
            tlm = mul([1, 0, 0, 1, 0, -gs.tl], tlm)
            tm = tlm.slice()
            break
          case 'Tj':
            if (isStr(a[0])) show(a[0])
            break
          case "'":
            tlm = mul([1, 0, 0, 1, 0, -gs.tl], tlm)
            tm = tlm.slice()
            if (isStr(a[0])) show(a[0])
            break
          case '"':
            gs.tw = a[0]
            gs.tc = a[1]
            tlm = mul([1, 0, 0, 1, 0, -gs.tl], tlm)
            tm = tlm.slice()
            if (isStr(a[2])) show(a[2])
            break
          case 'TJ':
            if (Array.isArray(a[0]))
              for (const item of a[0]) {
                if (isStr(item)) show(item)
                else if (typeof item === 'number') tm = mul([1, 0, 0, 1, (-item / 1000) * gs.fs * gs.th, 0], tm)
              }
            break
          case 'Do': {
            const xobjects = isDict(resources) ? doc.get(resources.XObject) : null
            const xo = isDict(xobjects) ? doc.get(xobjects[a[0]]) : null
            if (!isStream(xo)) break
            if (xo.dict.Subtype === 'Form') {
              flushRun()
              if (depth < 8) this.formWithin(xo, gs, resources, depth + 1)
            } else if (xo.dict.Subtype === 'Image') this.image(xo, gs, resources)
            break
          }
          case 'BI': {
            // An inline picture: its data skipped (it has no place in the file to decode from).
            const b = L.b
            let p = L.p
            while (p + 3 < b.length && !(b[p] === 73 && b[p + 1] === 68 && WHITE[b[p + 2]])) p++
            p += 3
            while (p + 2 < b.length && !(WHITE[b[p - 1]] && b[p] === 69 && b[p + 1] === 73 && (p + 2 >= b.length || WHITE[b[p + 2]]))) p++
            L.p = p + 2
            this.problem('inline pictures are not drawn')
            break
          }
          case 'd0':
          case 'd1':
          case 'BX':
          case 'EX':
          case 'MP':
          case 'DP':
          case 'BMC':
          case 'BDC':
          case 'EMC':
          case 'ri':
          case 'i':
          default:
            break
        }
      } catch (e) {
        // A bad operator is skipped, as viewers do.
      }
      args.length = 0
    }
    flushRun()
  }

  formWithin(xo, gs, resources, depth) {
    const dict = xo.dict
    const matrix = Array.isArray(dict.Matrix) ? dict.Matrix.map((v) => this.doc.get(v)) : [1, 0, 0, 1, 0, 0]
    const m = mul(matrix, gs.ctm)
    let clip = gs.clip
    const bbox = boxOf(this.doc, dict.BBox)
    if (bbox) {
      const box = rectClip(m, bbox)
      if (box) clip = intersect(clip, box)
    }
    if (clip[2] <= clip[0] || clip[3] <= clip[1]) return
    let bytes
    try {
      bytes = this.doc.streamBytes(xo)
    } catch (e) {
      this.problem(e.message)
      return
    }
    // The form starts from the graphics state around it.
    this.run(bytes, dict.Resources || resources, m, depth, clip, gs)
  }

  image(xo, gs, resources) {
    const doc = this.doc
    const dict = xo.dict
    const m = gs.ctm
    const corners = [apply(m, 0, 0), apply(m, 1, 0), apply(m, 0, 1), apply(m, 1, 1)]
    const x = Math.min(...corners.map((c) => c[0]))
    const y = Math.min(...corners.map((c) => c[1]))
    const w = Math.max(...corners.map((c) => c[0])) - x
    const h = Math.max(...corners.map((c) => c[1])) - y
    const clip = gs.clip
    if (w < 0.5 || h < 0.5 || !(x + w >= clip[0] && x <= clip[2] && y + h >= clip[1] && y <= clip[3])) return
    // The picture's unit square onto the screen, its first row at the top:
    // an upright one is a box, anything else a matrix.
    const upright = Math.abs(m[1]) < 1e-6 && Math.abs(m[2]) < 1e-6 && m[0] > 0 && m[3] < 0
    const place = upright
      ? { x: r1(x), y: r1(y), w: r1(w), h: r1(h) }
      : { x: r1(x), y: r1(y), w: r1(w), h: r1(h), m: [m[0], m[1], -m[2], -m[3], m[2] + m[4], m[3] + m[5]].map((v) => Math.round(v * 1000) / 1000) }
    // The size to decode it at: as many pixels as it covers.
    place.pw = Math.max(1, Math.round(Math.hypot(m[0], m[1])))
    place.ph = Math.max(1, Math.round(Math.hypot(m[2], m[3])))
    const filters = listOf(doc.get(dict.Filter)).map((f) => FILTER_NAMES[f] || f)
    const parms = listOf(doc.get(dict.DecodeParms)).map((p) => doc.get(p))
    const width = doc.get(dict.Width) || doc.get(dict.W)
    const height = doc.get(dict.Height) || doc.get(dict.H)
    const placeholder = (why) => {
      this.problem(why)
      this.out.ops.push({ t: 'path', d: `M${r1(x)} ${r1(y)}h${r1(w)}v${r1(h)}h${r1(-w)}Z`, fill: '#e6e6e6', stroke: '#b0b0b0', width: 1, clip })
    }
    if (!width || !height) return
    const src = { offset: xo.start, length: xo.length, width, height }
    const decode = doc.get(dict.Decode)
    const mask = dict.ImageMask === true || dict.IM === true
    // Where it is see-through: a soft mask (grey samples, the opacity) or a
    // stencil (1 is not painted), both decoded beside it.
    const soft = doc.get(dict.SMask)
    const stencil = doc.get(dict.Mask)
    const maskOf = (m, stencilMask) => {
      const f = listOf(doc.get(m.dict.Filter)).map((v) => FILTER_NAMES[v] || v)
      if (f.length > 1 || (f.length === 1 && f[0] !== 'FlateDecode')) return null
      const p = listOf(doc.get(m.dict.DecodeParms)).map((v) => doc.get(v))[0]
      const d = doc.get(m.dict.Decode)
      const flipped = Array.isArray(d) && d[0] === 1
      return {
        offset: m.start,
        length: m.length,
        inflate: f[0] === 'FlateDecode',
        pixels: {
          width: doc.get(m.dict.Width),
          height: doc.get(m.dict.Height),
          colors: 1,
          bits: stencilMask ? 1 : doc.get(m.dict.BitsPerComponent) || 8,
          predictor: (p && p.Predictor) || 1,
          invert: stencilMask ? !flipped : flipped,
        },
      }
    }
    if (!mask && isStream(soft)) src.mask = maskOf(soft, false)
    else if (!mask && isStream(stencil)) src.mask = maskOf(stencil, true)
    if (src.mask && !(src.mask.pixels.width > 0 && src.mask.pixels.height > 0)) delete src.mask
    if (filters.length === 1 && filters[0] === 'DCTDecode') {
      const cs = colorSpace(doc, dict.ColorSpace, resources)
      if (cs.n === 4) this.problem('CMYK pictures may show in odd colours')
      this.out.ops.push({ t: 'image', ...place, src, clip })
      return
    }
    if (filters.length > 1 || (filters.length === 1 && filters[0] !== 'FlateDecode')) {
      placeholder(`${filters.join(' + ')} pictures are not shown`)
      return
    }
    const bits = mask ? 1 : doc.get(dict.BitsPerComponent) || 8
    const pixels = { width, height, bits, predictor: (parms[0] && parms[0].Predictor) || 1 }
    if (mask) {
      // A stencil: the fill colour where the samples say, on white.
      const paint = gs.fill && gs.fill.startsWith('#') ? gs.fill.slice(1) : '000000'
      pixels.colors = 1
      pixels.palette = Array.isArray(decode) && decode[0] === 1 ? `ffffff${paint}` : `${paint}ffffff`
    } else {
      const cs = colorSpace(doc, dict.ColorSpace, resources)
      if (cs.indexed) {
        pixels.colors = 1
        let pal = ''
        for (let i = 0; i <= cs.hival && i < 256; i++) {
          const rgb = cs.rgb([i]) || [1, 1, 1]
          pal += hex2(rgb[0]) + hex2(rgb[1]) + hex2(rgb[2])
        }
        pixels.palette = pal
      } else if (cs.n === 1 || cs.n === 3 || cs.n === 4) {
        pixels.colors = cs.n
        if (cs.n === 1 && Array.isArray(decode) && decode[0] === 1) pixels.invert = true
        // A spot colour's tint is ink: 1 is dark.
        const spaceName = Array.isArray(doc.get(dict.ColorSpace)) ? doc.get(doc.get(dict.ColorSpace)[0]) : ''
        if (spaceName === 'Separation' || spaceName === 'DeviceN') pixels.invert = !pixels.invert
      } else {
        placeholder('pictures in this colour space are not shown')
        return
      }
    }
    src.inflate = filters[0] === 'FlateDecode'
    src.pixels = pixels
    this.out.ops.push({ t: 'image', ...place, src, clip })
  }
}

function growBox(box, a, b, size) {
  box[0] = Math.min(box[0], a[0], b[0])
  box[1] = Math.min(box[1], a[1] - size, b[1] - size)
  box[2] = Math.max(box[2], a[0], b[0])
  box[3] = Math.max(box[3], a[1] + size * 0.3, b[1] + size * 0.3)
}

function intersect(a, b) {
  return [Math.max(a[0], b[0]), Math.max(a[1], b[1]), Math.min(a[2], b[2]), Math.min(a[3], b[3])]
}

// A user-space rectangle through m, when it stays a rectangle of the screen.
function rectClip(m, rect) {
  if (Math.abs(m[1]) > 1e-6 || Math.abs(m[2]) > 1e-6) {
    if (Math.abs(m[0]) > 1e-6 || Math.abs(m[3]) > 1e-6) return null
  }
  const a = apply(m, rect[0], rect[1])
  const b = apply(m, rect[2], rect[3])
  return [Math.min(a[0], b[0]), Math.min(a[1], b[1]), Math.max(a[0], b[0]), Math.max(a[1], b[1])]
}

export { PdfError }
